```javascript
/*
Explanation:
The issue arises because printWindow.print() starts the printing process asynchronously,
meaning the browser initiates the print dialog but JavaScript execution continues immediately.
Calling printWindow.close() right after printWindow.print() often closes the window
before the browser has fully prepared and displayed the print dialog, or before the user
has interacted with it.

To fix this, you need to delay closing the window until after the print process
has had a chance to complete (either the user prints or cancels the dialog).
*/

// Assuming printWindow is already obtained, e.g., via:
// let printWindow = window.open('', '_blank');
// if (!printWindow) { alert('Popup blocked?'); return; }

// Write content to the window
// Note: Using default 'text/html' is usually better unless 'text/plain' is specifically required.
// Writing minimal HTML helps structure the content.
printWindow.document.open(); // Defaults to 'text/html'
printWindow.document.write('<html><head><title>Print Content</title></head><body>');
printWindow.document.write("toto"); // Your specific content
printWindow.document.write('</body></html>');
printWindow.document.close();
printWindow.focus(); // Bring the new window to the front

// --- Solution 1: Using onafterprint (Recommended) ---
// This event fires after the print dialog is closed.
if ('onafterprint' in printWindow) {
    printWindow.onafterprint = function() {
        // Check if the window is still open before trying to close it
        if (printWindow && !printWindow.closed) {
            printWindow.close();
        }
    };
    // Trigger the print dialog
    printWindow.print();
} else {
    // --- Solution 2: Fallback using setTimeout (Less Reliable) ---
    // If onafterprint is not supported, use a delay.
    printWindow.print();
    setTimeout(function() {
        // Check if the window is still open before trying to close it
        if (printWindow && !printWindow.closed) {
            printWindow.close();
        }
    }, 1000); // 1000ms (1 second) delay. Adjust if necessary.
    console.warn("Browser does not support 'onafterprint', using setTimeout fallback.");
}

/*
Key Points:

1.  **Asynchronous `print()`:** The `print()` command doesn't wait for the user.
2.  **`onafterprint`:** The best solution. It waits for the print dialog interaction to finish. Widely supported in modern browsers.
3.  **`setTimeout`:** A less reliable fallback. The delay is a guess and might not be long enough, or might be unnecessarily long.
4.  **`document.open()` type:** Consider if `text/plain` is truly needed or if the default `text/html` is more appropriate for browser rendering/printing.
5.  **Popup Blockers:** Ensure the `window.open()` call successfully creates `printWindow`. Popup blockers can interfere.
*/
```

