//    - `GET /`: Simple welcome message (text/plain).
//    - `GET /items`: Retrieve a list of items (application/json).
//    - `POST /items`: Add a new item to the list (expects application/json, returns application/json).
// 4. Data Structure:
//    - Define a `struct` named `Item` with fields like `ID` (string) and `Name` (string).
//    - Use an in-memory slice `[]Item` to store the items for simplicity.
//    - Use a `sync.Mutex` to protect concurrent access to the shared item slice.
// 5. Server Structure:
//    - `main` function:
//        - Initializes the item slice.
//        - Sets up request handlers using `http.HandleFunc`. A single handler for `/items` will manage both GET and POST via method switching.
//        - Starts the HTTP server using `http.ListenAndServe`.
//    - Handler Functions:
//        - `rootHandler`: Handles `GET /`.
//        - `itemsHandler`: Handles `/items`. Checks `r.Method` (GET or POST).
//            - If GET: Encodes the item slice to JSON and sends it.
//            - If POST: Decodes the JSON request body into a new `Item`, appends it to the slice (with mutex protection), and sends a success response (e.g., the added item or StatusCreated).
//        - Include basic error handling (e.g., bad requests, method not allowed, JSON errors).
// 6. Dependencies: `net/http`, `encoding/json`, `log`, `sync`, `fmt` (maybe `io` for reading body).

// --- Go Server Code ---
package main

import (
	"encoding/json"
	"fmt"
	"io"
	"log"
	"net/http"
	"sync"
	"strconv"
	"time"
)

// Item represents the data structure for our items.
type Item struct {
	ID   string `json:"id"`
	Name string `json:"name"`
}

var (
	items      []Item      // In-memory store for items
	itemsMutex sync.Mutex  // Mutex to protect concurrent access
	nextID     int         // Simple ID counter
)

// rootHandler handles requests to the root path "/".
func rootHandler(w http.ResponseWriter, r *http.Request) {
	if r.Method != http.MethodGet {
		http.Error(w, "Method Not Allowed", http.StatusMethodNotAllowed)
		return
	}
	if r.URL.Path != "/" {
		http.NotFound(w, r)
		return
	}
	fmt.Fprintln(w, "Welcome to the Go Item Server!")
}

// itemsHandler handles requests to the "/items" path for GET and POST.
func itemsHandler(w http.ResponseWriter, r *http.Request) {
	switch r.Method {
	case http.MethodGet:
		handleGetItems(w, r)
	case http.MethodPost:
		handlePostItems(w, r)
	default:
		http.Error(w, "Method Not Allowed", http.StatusMethodNotAllowed)
	}
}

// handleGetItems handles GET requests to "/items".
func handleGetItems(w http.ResponseWriter, r *http.Request) {
	itemsMutex.Lock()
	defer itemsMutex.Unlock()

	w.Header().Set("Content-Type", "application/json")
	if err := json.NewEncoder(w).Encode(items); err != nil {
		log.Printf("Error encoding items: %v", err)
		http.Error(w, "Failed to encode response", http.StatusInternalServerError)
	}
}

// handlePostItems handles POST requests to "/items".
func handlePostItems(w http.ResponseWriter, r *http.Request) {
	// Read request body
	body, err := io.ReadAll(r.Body)
	if err != nil {
		http.Error(w, "Unable to read request body", http.StatusBadRequest)
		return
	}
	defer r.Body.Close()

	// Decode JSON into a temporary struct (only need Name from user)
	var newItemData struct {
		Name string `json:"name"`
	}
	if err := json.Unmarshal(body, &newItemData); err != nil {
		http.Error(w, "Invalid JSON format: "+err.Error(), http.StatusBadRequest)
		return
	}

	if newItemData.Name == "" {
		http.Error(w, "Item name cannot be empty", http.StatusBadRequest)
		return
	}

	itemsMutex.Lock()
	defer itemsMutex.Unlock()

	// Create new item with generated ID
	nextID++
	newItem := Item{
		ID:   strconv.Itoa(nextID),
		Name: newItemData.Name,
	}

	// Add to the slice
	items = append(items, newItem)
	log.Printf("Added item: %+v", newItem)

	// Respond with the created item and status 201
	w.Header().Set("Content-Type", "application/json")
	w.WriteHeader(http.StatusCreated)
	if err := json.NewEncoder(w).Encode(newItem); err != nil {
		log.Printf("Error encoding newly created item: %v", err)
		// Hard to send error now as header is written, log it.
	}
}

func main() {
	// Initialize items slice and ID counter
	items = []Item{}
	nextID = 0
	// Seed with some data
	items = append(items, Item{ID: strconv.Itoa(nextID), Name: "Initial Item"})


	// Register handlers
	http.HandleFunc("/", rootHandler)
	http.HandleFunc("/items", itemsHandler)

	// Define server port
	port := "8080"
	log.Printf("Server starting on http://localhost:%s", port)

	// Start the server
	server := &http.Server{
        Addr:         ":" + port,
        ReadTimeout:  10 * time.Second,
        WriteTimeout: 10 * time.Second,
    }
	if err := server.ListenAndServe(); err != nil {
		log.Fatalf("Server failed to start: %v", err)
	}
}

