  const inputRef = useRef<HTMLInputElement>(null);
  const listRef = useRef<HTMLUListElement>(null);

  const [debouncedInputValue] = useDebounce(inputValue, debounceMs);

  // Memoize the options set for efficient validation lookup
  const optionsSet = useMemo(() => new Set(options.map(opt => opt.toLowerCase())), [options]);

  // Default validation logic if no custom validate function is provided
  const defaultValidate = useCallback(
    (value: string): boolean => {
      if (value === '') return true; // Empty is often considered valid until submission
      return optionsSet.has(value.toLowerCase());
    },
    [optionsSet]
  );

  const runValidation = useCallback(
    (value: string) => {
      const validator = validate || defaultValidate;
      setIsValid(validator(value));
    },
    [validate, defaultValidate]
  );

  // Memoize filtered options based on the debounced input value
  const filteredOptions = useMemo(() => {
    const lowerInput = debouncedInputValue.trim().toLowerCase();
    if (!lowerInput) {
