        results.push(opt);
        if (results.length >= maxDisplayedOptions) {
          break;
        }
      }
    }
    return results;
  }, [debouncedInputValue, options]);

  // Show/hide dropdown based on filtered options and input focus
  useEffect(() => {
    // Show dropdown if input is focused, has value, and there are filtered options
    if (filteredOptions.length > 0 && document.activeElement === inputRef.current) {
