// Modular exponentiation: computes (base^exp) % mod efficiently.
// Uses u128 intermediate results for safety, though u64 is likely sufficient here.
fn modPow(base: u64, exp: u64, mod: u64) u64 {
    if (mod == 1) return 0; // Edge case

    var result: u128 = 1;
    var b: u128 = base % mod;
    var e = exp;

    while (e > 0) {
        // If e is odd, multiply result with b
        if (e & 1 == 1) {
            result = (result * b) % mod;
        }
        // e = e / 2
        e >>= 1;
        // b = b^2 % mod
        b = (b * b) % mod;
    }
    return @intCast(u64, result);
}

