// Modular exponentiation: (base^exponent) % modulus
// Uses u128 for intermediate calculations to prevent overflow, although
// u64 might be sufficient given the specific modulus in this problem.
fn modPow(base: u64, exponent: u64, modulus: u64) u64 {
    if (modulus == 1) return 0; // Edge case

    var result: u128 = 1;
    var b: u128 = base % modulus;
    var exp = exponent;

