impl FolderMonitorApp {
    // Helper to add events to the log
    fn log_event(&mut self, message: String) {
        println!("Log: {}", message); // Also print to console for debugging
        self.event_log.push(message);
        // Optional: Limit log size
        const MAX_LOG_ENTRIES: usize = 100;
        if self.event_log.len() > MAX_LOG_ENTRIES {
            self.event_log.remove(0);
        }
    }

    // Starts monitoring the input folder in a separate thread
    fn start_monitoring(&mut self) {
        if self.is_monitoring {
            self.log_event("Already monitoring.".to_string());
            return;
        }
        if self.input_folder.is_none() {
            self.log_event("Input folder not selected. Cannot start monitoring.".to_string());
            return;
        }

        let input_path = self.input_folder.clone().unwrap(); // Checked is_none above
        let (tx, rx) = mpsc::channel::<String>(); // Create channel for this monitoring session
        self.event_receiver = Some(rx); // Store receiver for the update loop
        self.is_monitoring = true;

        self.log_event(format!("Starting monitoring on: {}", input_path.display()));

        // Spawn the watcher thread
        thread::spawn(move || {
            // Event handler closure - captures the sender `tx`
            let handler = move |res: Result<Event, notify::Error>| {
                match res {
                    Ok(event) => {
                        // Filter specifically for file creation events
                        if matches!(event.kind, EventKind::Create(CreateKind::File)) {
                            // Get the path(s) of the created file(s)
                            for path in event.paths {
                                let msg = format!("New file detected: {}", path.display());
                                // Send message to GUI thread. If send fails, GUI likely closed.
                                if tx.send(msg).is_err() {
                                    eprintln!("GUI channel closed, watcher thread stopping.");
                                    // Break the implicit loop of the watcher/handler by returning
                                    // (This depends on notify's implementation detail, cleaner would be explicit stop)
                                    return;
                                }
                            }
                        }
                        // Optionally log other events for debugging
                        // else {
                        //     println!("Other event: {:?}", event);
                        // }
                    }
                    Err(e) => {
                        let err_msg = format!("Watcher error: {:?}", e);
                        // Attempt to send error to GUI. Ignore error if channel closed.
                        let _ = tx.send(err_msg);
                    }
                }
            };

            // Create and configure the watcher within the thread
            let mut watcher = match RecommendedWatcher::new(handler, notify::Config::default()) {
                 Ok(w) => w,
                 Err(e) => {
                    // Send error message back to the main thread
                    let _ = tx.send(format!("Failed to create watcher: {:?}", e));
                    // Exit the thread if watcher creation fails
                    return;
                 }
            };

            // Start watching the specified path
            if let Err(e) = watcher.watch(&input_path, RecursiveMode::NonRecursive) {
                // Send error message back to the main thread
                let _ = tx.send(format!("Failed to start watching '{}': {:?}", input_path.display(), e));
                // Exit the thread if watching fails
                return;
            }

            // The watcher runs implicitly. Keep the thread alive.
