        if let Some(rx) = &self.event_receiver {
            loop {
                match rx.try_recv() {
                    Ok(msg) => {
                        self.log_event(msg);
                    }
                    Err(TryRecvError::Empty) => {
                        // No more messages in the channel for now
                        break;
                    }
                    Err(TryRecvError::Disconnected) => {
                        // Sender was dropped (watcher thread ended or panicked)
                        self.log_event("Watcher thread stopped or disconnected.".to_string());
                        self.is_monitoring = false; // Update state
                        self.event_receiver = None; // Clear the receiver
                        break;
                    }
                }
            }
        }

        // Define the GUI layout
        egui::CentralPanel::default().show(ctx, |ui| {
            ui.heading("Folder Monitor Application");
            ui.separator();

            // Helper function for folder selection rows
            let mut select_folder = |label: &str, folder_path: &mut Option<PathBuf>| {
                 ui.horizontal(|ui| {
