                            .as_ref()
                            .map_or("Not Selected", |p| p.to_string_lossy().to_string().into()) // Use to_string_lossy
                    ));
                });
            };

            select_folder("Input Folder", &mut self.input_folder);
            select_folder("Output Folder", &mut self.output_folder);
            select_folder("Done Folder", &mut self.done_folder);

            ui.separator();

            // Start Button
            // Disable button if already monitoring or input folder not set
