            let event_handler = move |res: Result<notify::Event, notify::Error>| {
                match res {
                    Ok(event) => {
                        // Filter specifically for creation events ("new file arrives")
                        if event.kind.is_create() {
                            let paths: Vec<String> = event.paths.iter()
                                .map(|p| p.display().to_string())
                                .collect();
                             let log_msg = format!("New file detected: {:?} at [{}]",
                                                  event.kind, paths.join(", "));
                            // Use try_send to avoid blocking watcher if channel is full
                            if let Err(e) = log_sender.try_send(log_msg) {
                                eprintln!("Error sending log message: {}", e);
                            }
                        }
                         // Can add logging for other event types if needed
                    }
                    Err(e) => {
                        let _ = log_sender.try_send(format!("Watcher error: {:?}", e));
                    }
                }
            };

            // Create and configure the watcher
            match RecommendedWatcher::new(event_handler, notify::Config::default()) {
                Ok(mut watcher) => {
                    if let Err(e) = watcher.watch(&input_path, RecursiveMode::NonRecursive) {
                        self.add_log(format!("Error starting watcher: {:?}", e));
                        self.log_receiver = None; // Clear receiver if watch fails
                    } else {
                        self.add_log(format!("Started monitoring: {}", input_path.display()));
                        self._watcher = Some(watcher); // Store watcher
                        self.monitoring_active = true;
                    }
                }
                Err(e) => {
                     self.add_log(format!("Error creating watcher: {:?}", e));
                     self.log_receiver = None; // Clear receiver if creation fails
                }
            }
        } else {
            self.add_log("Please select an input folder first.".to_string());
        }
    }

    // Stop the file system watcher
    fn stop_monitoring(&mut self) {
        if self.monitoring_active {
            // Dropping the watcher stops it
            self._watcher = None;
            // Clear the receiver
            self.log_receiver = None;
            self.monitoring_active = false;
            self.add_log("Monitoring stopped.".to_string());
        }
    }
}

// Implement eframe::App trait
impl eframe::App for FolderMonitorApp {
    fn update(&mut self, ctx: &egui::Context, _frame: &mut eframe::Frame) {
        // Process messages from watcher
        if let Some(receiver) = &self.log_receiver {
            loop {
                match receiver.try_recv() {
                    Ok(log_msg) => self.add_log(log_msg),
                    Err(TryRecvError::Empty) => break, // No more messages
                    Err(TryRecvError::Disconnected) => {
                        self.add_log("Watcher disconnected unexpectedly.".to_string());
                        if self.monitoring_active {
                           self.stop_monitoring(); // Clean up state
                        }
                        break;
                    }
                }
            }
        }

        egui::CentralPanel::default().show(ctx, |ui| {
            ui.heading("Folder Monitor");
            ui.separator();

            // Folder selectors
            ui.horizontal(|ui| {
                if ui.button("Select Input Folder").clicked() {
                    if let Some(path) = FileDialog::new().pick_folder() {
                        if self.monitoring_active { self.stop_monitoring(); }
                        self.input_dir = Some(path);
                        self.add_log("Input folder selected. Press Start to monitor.".to_string());
                    }
                }
                ui.label(format!("Input: {}", self.input_dir.as_ref().map_or("Not Selected", |p| p.display().to_string())));
            });
            ui.horizontal(|ui| {
                if ui.button("Select Output Folder").clicked() {
                    self.output_dir = FileDialog::new().pick_folder();
                }
                ui.label(format!("Output: {}", self.output_dir.as_ref().map_or("Not Selected", |p| p.display().to_string())));
            });
            ui.horizontal(|ui| {
                if ui.button("Select Done Folder").clicked() {
                    self.done_dir = FileDialog::new().pick_folder();
                }
                ui.label(format!("Done: {}", self.done_dir.as_ref().map_or("Not Selected", |p| p.display().to_string())));
            });
            ui.separator();

            // Control buttons
            ui.horizontal(|ui|{
                let start_enabled = self.input_dir.is_some() && !self.monitoring_active;
                if ui.add_enabled(start_enabled, egui::Button::new("Start Monitoring")).clicked() {
                    self.start_monitoring();
                }
                let stop_enabled = self.monitoring_active;
                 if ui.add_enabled(stop_enabled, egui::Button::new("Stop Monitoring")).clicked() {
                    self.stop_monitoring();
                 }
            });
            ui.separator();

            // Log display
            ui.label("Event Log:");
            egui::ScrollArea::vertical()
                .auto_shrink([false, false])
                .stick_to_bottom(true)
                .show(ui, |ui| {
                    for log_entry in &self.logs {
                        ui.label(log_entry);
                    }
                });
        });

        // Request repaint if monitoring to show logs promptly
        if self.monitoring_active {
             ctx.request_repaint_after(std::time::Duration::from_millis(100));
        }
    }
}

