        initial_window_size: Some(egui::vec2(600.0, 400.0)),
        ..Default::default()
    };
    eframe::run_native(
        "Folder Monitor App",
        options,
        Box::new(|_cc| Box::new(FolderMonitorApp::default())),
    )
}

