// Function to perform linear interpolation for a single point x,
// assuming x_original corresponds to indices 0, 1, 2,...
double linearInterpolateSimple(double x, const std::vector<double>& y_original) {
    int n = y_original.size();
    double x_max = static_cast<double>(n - 1);

    // Handle edge cases: points outside or exactly at the boundaries
    if (x <= 0.0) {
        return y_original.front();
    }
    // Check against the maximum x value (index)
    // Using >= handles the case where x is exactly the last index
    if (x >= x_max) {
        return y_original.back();
    }

    // Find the interval [index, index + 1] that contains x
    // Since original x are 0, 1, 2..., the lower index is floor(x)
    int index = static_cast<int>(x); // floor(x) for positive x

    // Calculate the fraction 't' within the interval
    // t = (x - x_original[index]) / (x_original[index+1] - x_original[index])
    // Since x_original[index] = index and denominator is 1, t = x - index
    double t = x - static_cast<double>(index);

    // Linear interpolation formula: y = y0 + t * (y1 - y0)
    return y_original[index] + t * (y_original[index + 1] - y_original[index]);
}

