// y is the vector of original y values
double linear_interpolate(double x, const std::vector<double>& y) {
    int n = y.size();
    if (n == 0) {
        // Handle empty vector case if necessary, maybe throw an error or return NaN
        return 0.0; // Or some other indicator of error
    }
    if (n == 1) {
        return y[0]; // Only one point, return its value
