    // Clamp x to the range [0, x_max] to handle potential floating point inaccuracies
    // or if extrapolation is not desired (matching interp1d default behavior without extrapolation)
    if (x <= 0.0) {
        return y.front();
    }
    if (x >= x_max) {
        return y.back();
    }

    // Find the index of the interval [x_i, x_{i+1}] containing x
    // Since x_original[i] = i, the lower index is floor(x)
    int index_low = static_cast<int>(std::floor(x));

    // Ensure index_low is valid, though clamping x should make this redundant
