    // Calculate the fractional distance of x within the interval [index_low, index_low + 1]
    double fraction = x - static_cast<double>(index_low);

    // Perform linear interpolation: y = y0 + fraction * (y1 - y0)
    return y[index_low] + fraction * (y[index_low + 1] - y[index_low]);
}

