import java.util.Collections

/**
 * Calculates the minimum number of key pushes required to type the given word
 * after optimally remapping the telephone keypad keys (2-9).
 *
 * @param word The input string containing lowercase English letters.
 * @return The minimum number of pushes needed.
 */
fun minimumPushes(word: String): Int {
    // 1. Count the frequency of each character.
    // Use a map or an array. An array is efficient for fixed alphabet size.
    val counts = IntArray(26) { 0 }
    for (char in word) {
        // Increment the count for the character. 'a' corresponds to index 0.
        counts[char - 'a']++
    }

    // 2. Collect the frequencies of characters that actually appear in the word.
    val frequencies = mutableListOf<Int>()
    for (count in counts) {
        if (count > 0) {
            frequencies.add(count)
        }
    }

    // 3. Sort the frequencies in descending order.
    // The most frequent characters should be assigned to the lowest push cost positions.
    frequencies.sortDescending()

    // 4. Calculate the total minimum pushes.
    // There are 8 keys (2-9).
    // The first 8 most frequent letters (indices 0-7) can be assigned to 1-push positions.
    // The next 8 most frequent letters (indices 8-15) must be assigned to 2-push positions.
    // The next 8 most frequent letters (indices 16-23) must be assigned to 3-push positions.
    // The last 2 most frequent letters (indices 24-25) must be assigned to 4-push positions.
    var totalPushes = 0
    for (i in frequencies.indices) {
        val frequency = frequencies[i]
        // Calculate the push cost based on the rank (index i).
        // Integer division (i / 8) gives the tier (0, 1, 2, ...).
        // Add 1 to get the push cost (1, 2, 3, ...).
        val pushCost = (i / 8) + 1
        totalPushes += frequency * pushCost
    }

    // Constraints check: word.length <= 10^5. Max distinct chars = 26.
    // Max push cost = (25/8)+1 = 4.
    // Max possible sum approx 10^5 * 4 = 4*10^5, which fits within Int.
    // However, using Long might be safer in general competitive programming.
    // Let's stick to Int as per the prompt's likely expectation unless overflow is certain.
    return totalPushes
}
