#include <iostream>
#include <memory> // Required for std::unique_ptr, std::make_unique
#include <utility> // Required for std::move

// Template Node structure
template <typename T>
struct Node {
    T data;
    std::unique_ptr<Node<T>> next; // unique_ptr owns the next node

    // Constructor to initialize data and next pointer
    Node(T val) : data(std::move(val)), next(nullptr) {}

    // Optional: Destructor to show when nodes are deleted
    ~Node() {
        // std::cout << "Node with data " << data << " destroyed." << std::endl;
    }
};

// Template LinkedList class
template <typename T>
class LinkedList {
private:
    std::unique_ptr<Node<T>> head; // unique_ptr owns the head node

public:
    // Constructor
    LinkedList() : head(nullptr) {}

    // Destructor is defaulted; unique_ptr handles cleanup automatically
    ~LinkedList() = default;

    // Since unique_ptr manages ownership, disable copy operations
    LinkedList(const LinkedList&) = delete;
    LinkedList& operator=(const LinkedList&) = delete;

    // Enable move operations (transfer ownership)
    LinkedList(LinkedList&&) = default;
    LinkedList& operator=(LinkedList&&) = default;

    // Add a node to the front of the list
    void push_front(T value) {
        auto newNode = std::make_unique<Node<T>>(std::move(value));
        // The new node's 'next' takes ownership of the current head
        newNode->next = std::move(head);
        // The list's 'head' takes ownership of the new node
        head = std::move(newNode);
    }

    // Remove the node from the front of the list
    void pop_front() {
        if (!head) {
            std::cerr << "List is empty, cannot pop." << std::endl;
            return;
        }
        // head takes ownership of the node pointed to by the current head's next
        // The original head node is destroyed when the unique_ptr managing it
        // (the one previously stored in 'head') is reset by the move assignment.
        head = std::move(head->next);
    }

    // Print the list's contents
    void print() const {
        Node<T>* current = head.get(); // Use get() for temporary raw pointer access
        while (current) {
            std::cout << current->data << " -> ";
            current = current->next.get(); // Move to the next node via its raw pointer
        }
        std::cout << "nullptr" << std::endl;
    }

    // Check if the list is empty
    bool is_empty() const {
        return !head;
    }
};

// Example usage
int main() {
    std::cout << "Creating list 'myList'..." << std::endl;
    LinkedList<int> myList;
    myList.push_front(30);
    myList.push_front(20);
    myList.push_front(10);

    std::cout << "myList: ";
    myList.print(); // Output: 10 -> 20 -> 30 -> nullptr

    std::cout << "\nPopping front element..." << std::endl;
    myList.pop_front();
    std::cout << "myList after pop: ";
    myList.print(); // Output: 20 -> 30 -> nullptr

