C++ does not have built-in garbage collection in the same way as languages like Java or C#. However, you can achieve automatic memory management for data structures like linked lists by leveraging C++'s RAII (Resource Acquisition Is Initialization) principle, most commonly implemented using **smart pointers**.

The standard library provides `std::unique_ptr` and `std::shared_ptr`. For a simple singly linked list where each node is clearly owned by the preceding node (or the list head), `std::unique_ptr` is the most appropriate and efficient choice. It ensures exclusive ownership, and when the `unique_ptr` goes out of scope or is reset, it automatically deletes the managed object.

Here's an example implementation of a singly linked list using `std::unique_ptr` for automatic memory management:

```cpp
#include <iostream>
#include <memory> // Required for std::unique_ptr, std::make_unique
#include <utility> // Required for std::move

template <typename T>
class LinkedList {
private:
    // Node structure using unique_ptr for the next node
    struct Node {
        T data;
        std::unique_ptr<Node> next;

        // Constructor for Node
        Node(T val) : data(std::move(val)), next(nullptr) {}
    };

    // Head of the list is also managed by a unique_ptr
    std::unique_ptr<Node> head;
    size_t node_count = 0; // Optional: Keep track of size

public:
    // Default constructor creates an empty list
    LinkedList() = default;

    // Destructor is automatically generated.
    // When the LinkedList object is destroyed, 'head' unique_ptr goes out of scope.
    // This destroys the first Node, which in turn destroys its 'next' unique_ptr,
    // causing a chain reaction that deletes all nodes automatically.
    ~LinkedList() = default;

    // --- Rule of 5/6 ---
    // unique_ptr makes the class non-copyable by default.
    // We explicitly delete copy operations for clarity.
    LinkedList(const LinkedList&) = delete;
    LinkedList& operator=(const LinkedList&) = delete;

    // Moving is allowed (and efficient)
    LinkedList(LinkedList&& other) noexcept = default;
    LinkedList& operator=(LinkedList&& other) noexcept = default;

    // Adds an element to the front of the list
    void push_front(T value) {
        // Create a new node. std::make_unique is preferred.
        auto new_node = std::make_unique<Node>(std::move(value));

        // The new node's 'next' takes ownership of the current head
        new_node->next = std::move(head);

        // The list's 'head' takes ownership of the new node
        head = std::move(new_node);

        node_count++;
    }

    // Removes the element from the front of the list
    void pop_front() {
        if (!head) {
            // List is empty, nothing to pop
            return;
        }
        // head takes ownership of the second node (head->next).
        // The original head node is automatically deleted when the unique_ptr
        // managing it is overwritten by std::move.
        head = std::move(head->next);
        node_count--;
    }

     // Removes the first node containing the specified value
    void remove(const T& value) {
        if (!head) return; // Empty list

        // Special case: remove the head node
        if (head->data == value) {
            pop_front();
            return;
        }

        // Find the node *before* the one to remove
        Node* current = head.get(); // Use raw pointer for iteration
        while (current->next && current->next->data != value) {
            current = current->next.get();
        }

        // If we found the node to remove (current->next is the target)
        if (current->next) {
            // Let temp take ownership of the node to remove's 'next' pointer
            std::unique_ptr<Node> node_after_removed = std::move(current->next->next);
            // Link current node to the node after the removed one
            current->next = std::move(node_after_removed);
            // The node originally pointed to by current->next is now deleted
            // as its unique_ptr went out of scope when moved from.
            node_count--;
        }
    }


    // Prints the list elements
    void print() const {
        Node* current = head.get(); // Use raw pointer for non-owning traversal
        while (current != nullptr) {
            std::cout << current->data << " -> ";
            current = current->next.get();
        }
        std::cout << "nullptr" << std::endl;
    }

    // Returns the number of nodes
    size_t size() const {
        return node_count;
    }

    // Checks if the list is empty
    bool empty() const {
        return !head; // or return node_count == 0;
    }
};

// Example Usage
int main() {
    LinkedList<int> list;

    std::cout << "Adding elements (30, 20, 10):" << std::endl;
    list.push_front(30);
    list.push_front(20);
    list.push_front(10);
    list.print(); // Output: 10 -> 20 -> 30 -> nullptr
    std::cout << "Size: " << list.size() << std::endl; // Output: Size: 3

    std::cout << "\nPopping front element:" << std::endl;
    list.pop_front();
    list.print(); // Output: 20 -> 30 -> nullptr
    std::cout << "Size: " << list.size() << std::endl; // Output: Size: 2

    std::cout << "\nRemoving element 30:" << std::endl;
    list.remove(30);
    list.print(); // Output: 20 -> nullptr
    std::cout << "Size: " << list.size() << std::endl; // Output: Size: 1


    std::cout << "\nAdding element 5:" << std::endl;
    list.push_front(5);
    list.print(); // Output: 5 -> 20 -> nullptr
    std::cout << "Size: " << list.size() << std::endl; // Output: Size: 2


    std::cout << "\nList goes out of scope now. Memory is automatically freed." << std::endl;
    // When 'list' goes out of scope here, its destructor is called,
    // which triggers the automatic deletion of all nodes via unique_ptr.

    return 0;
}
