      // Note: event.nativeEvent.lines contains the lines *as rendered* with numberOfLines applied.
      // If the number of rendered lines is greater than the limit, it definitely requires expansion.
      if (!isExpanded && event.nativeEvent.lines.length > numberOfLines) {
        // Avoid state update if already true to prevent potential loops
        if (!canBeTruncated) {
            setCanBeTruncated(true);
        }
      }
