  // Determine if the button should be shown
  const showSeeMore = !isExpanded && canBeTruncated;
  const showSeeLess = isExpanded && canBeTruncated; // Show "See less" only if expanded and truncation was possible

  return (
    <View style={containerStyle}>
      <Text
        style={[styles.text, textStyle]}
        numberOfLines={isExpanded ? undefined : numberOfLines}
        onTextLayout={onTextLayout} // Measure layout
        ellipsizeMode="tail" // Standard truncation indicator
      >
        {text}
      </Text>

      {/* Render "See more" or "See less" button if needed */}
      {(showSeeMore || showSeeLess) && (
