          accessibilityRole="button"
          accessibilityState={{ expanded: isExpanded }} // Better accessibility state
        >
          <Text style={[styles.buttonText, showSeeMore ? seeMoreStyle : seeLessStyle]}>
            {showSeeMore ? seeMoreText : seeLessText}
          </Text>
        </Pressable>
      )}
    </View>
  );
};

