**2. ViewModel (`AudioRecorderViewModel.swift`):**

This class handles the audio recording logic, permission requests, and state management.

```swift
import AVFoundation
import SwiftUI
import Combine

class AudioRecorderViewModel: ObservableObject {
    @Published var isRecording = false
    @Published var audioLevel: CGFloat = 0.0 // Normalized level (0.0 to 1.0)
    @Published var recordingURL: URL?
    @Published var recordingError: String?

    private var audioRecorder: AVAudioRecorder?
    private var audioSession: AVAudioSession = AVAudioSession.sharedInstance()
    private var meterTimer: Timer?
    private let minDbLevel: Float = -60.0 // Threshold for silence

    func startRecording() {
        requestPermission { [weak self] granted in
            guard let self = self else { return }
            guard granted else {
                DispatchQueue.main.async {
                    self.recordingError = "Microphone permission was denied."
                }
                return
            }

            DispatchQueue.main.async {
                self.setupAndStartRecording()
            }
        }
    }

    func stopRecording() {
        guard isRecording else { return }

        audioRecorder?.stop()
        meterTimer?.invalidate()
        meterTimer = nil
        audioRecorder = nil // Release the recorder instance

        DispatchQueue.main.async {
            self.isRecording = false
            self.audioLevel = 0.0 // Reset level
        }

        do {
            try audioSession.setActive(false)
        } catch {
            print("Failed to deactivate audio session: \(error.localizedDescription)")
            // Optionally update recordingError state
        }
    }

    private func requestPermission(completion: @escaping (Bool) -> Void) {
        switch audioSession.recordPermission {
        case .granted:
            completion(true)
        case .denied:
            completion(false)
        case .undetermined:
            audioSession.requestRecordPermission { granted in
                completion(granted)
            }
        @unknown default:
            completion(false)
        }
    }

    private func setupAndStartRecording() {
        let tempDir = FileManager.default.temporaryDirectory
        let fileName = "recording-\(UUID().uuidString).m4a"
        let fileURL = tempDir.appendingPathComponent(fileName)

        let settings: [String: Any] = [
            AVFormatIDKey: Int(kAudioFormatMPEG4AAC),
            AVSampleRateKey: 44100.0, // Standard sample rate
            AVNumberOfChannelsKey: 1,
            AVEncoderAudioQualityKey: AVAudioQuality.high.rawValue
        ]

        do {
            try audioSession.setCategory(.playAndRecord, mode: .default, options: [.defaultToSpeaker])
            try audioSession.setActive(true)

            audioRecorder = try AVAudioRecorder(url: fileURL, settings: settings)
            audioRecorder?.isMeteringEnabled = true
            audioRecorder?.prepareToRecord()
            audioRecorder?.record()

            self.recordingURL = fileURL // Store the URL
            self.isRecording = true
            self.recordingError = nil // Clear previous errors

            // Start timer for meter updates
            meterTimer = Timer.scheduledTimer(withTimeInterval: 0.05, repeats: true) { [weak self] _ in
                self?.updateMeter()
            }

        } catch {
            print("Failed to set up or start recording: \(error.localizedDescription)")
            self.recordingError = "Failed to start recording: \(error.localizedDescription)"
            self.isRecording = false
            // Ensure session is deactivated if setup fails partially
            try? audioSession.setActive(false)
        }
    }

    private func updateMeter() {
        guard let recorder = audioRecorder else { return }
        recorder.updateMeters()
        // Average power in dBFS (0 dBFS is max power, -160 dBFS is silence)
        let avgPower = recorder.averagePower(forChannel: 0)

        // Normalize the power level: map [-minDbLevel, 0] dB to [0, 1]
        let level = max(0, CGFloat((avgPower - minDbLevel) / (-minDbLevel))) // Ensure level >= 0

        DispatchQueue.main.async {
            self.audioLevel = level
        }
    }

    deinit {
        // Ensure resources are cleaned up if ViewModel is deallocated unexpectedly
        if isRecording {
            stopRecording()
        }
        meterTimer?.invalidate()
    }
}
```

**3. Equalizer View (`EqualizerView.swift`):**

This view displays the visualizer bars based on the audio level.

```swift
import SwiftUI

struct EqualizerView: View {
    let level: CGFloat // Normalized level (0.0 to 1.0)
    let numberOfBars: Int = 8
    let barCornerRadius: CGFloat = 3.0
    let minBarHeight: CGFloat = 5.0
    let maxBarHeight: CGFloat = 100.0

    var body: some View {
        HStack(alignment: .bottom, spacing: 4) {
            ForEach(0..<numberOfBars, id: \.self) { index in
                // Add some variation between bars for a more dynamic look
                let variationFactor = CGFloat.random(in: 0.7...1.0)
                let barHeight = max(minBarHeight, level * maxBarHeight * variationFactor)

                RoundedRectangle(cornerRadius: barCornerRadius)
                    .fill(Color.blue)
                    .frame(width: 10, height: barHeight)
                    // Use a subtle animation
                    .animation(.easeInOut(duration: 0.05), value: barHeight)
            }
        }
        .frame(height: maxBarHeight) // Ensure consistent height for the container
        .opacity(level > 0.01 ? 1.0 : 0.5) // Dim when silent/stopped
    }
}

