**2. ViewModel (`AudioRecorderViewModel.swift`)**

This class handles the audio recording logic, state management, and provides data for the view.

```swift
import Foundation
import AVFoundation
import SwiftUI // For ObservableObject, @Published, CGFloat

class AudioRecorderViewModel: ObservableObject {
    @Published var isRecording = false
    @Published var audioLevel: CGFloat = 0.0 // Normalized audio level (0.0 to 1.0) for the visualizer
    @Published var recordingFailed = false // To signal errors to the view
    @Published var errorMessage = "" // Store error messages
    @Published var permissionGranted = false
    @Published var permissionDeniedAlertShown = false

    private var audioRecorder: AVAudioRecorder?
    private var levelTimer: Timer?
    private var recordingURL: URL?

    private let recordingSettings: [String: Any] = [
        AVFormatIDKey: Int(kAudioFormatMPEG4AAC),
        AVSampleRateKey: 44100, // Standard sample rate
        AVNumberOfChannelsKey: 1,
        AVEncoderAudioQualityKey: AVAudioQuality.high.rawValue
    ]
    private let levelUpdateInterval: TimeInterval = 0.05 // Update frequency for visualizer

    init() {
        checkInitialPermission()
    }

    deinit {
        levelTimer?.invalidate()
        // Ensure recording is stopped if ViewModel is deallocated unexpectedly
        if isRecording {
            stopRecording()
        }
    }

    // MARK: - Permission Handling

    func checkInitialPermission() {
        switch AVAudioSession.sharedInstance().recordPermission {
        case .granted:
            permissionGranted = true
        case .denied:
            permissionGranted = false
        case .undetermined:
            permissionGranted = false
        @unknown default:
            permissionGranted = false
        }
    }

    func requestPermission() {
        AVAudioSession.sharedInstance().requestRecordPermission { [weak self] granted in
            DispatchQueue.main.async {
                self?.permissionGranted = granted
                if !granted {
                    self?.permissionDeniedAlertShown = true
                }
            }
        }
    }

    // MARK: - Recording Control

    func startRecording() {
        guard permissionGranted else {
            requestPermission() // Request if not yet granted or denied
            return
        }

        guard !isRecording else { return }

        let audioSession = AVAudioSession.sharedInstance()
        do {
            try audioSession.setCategory(.playAndRecord, mode: .default, options: [])
            try audioSession.setActive(true)

            recordingURL = generateRecordingURL()
            guard let url = recordingURL else {
                showError("Could not create recording file URL.")
                return
            }

            audioRecorder = try AVAudioRecorder(url: url, settings: recordingSettings)
            audioRecorder?.delegate = nil // Set delegate for advanced error handling if needed
            audioRecorder?.isMeteringEnabled = true

            if audioRecorder?.record() == true {
                isRecording = true
                recordingFailed = false
                startLevelTimer()
                print("Started recording to \(url.lastPathComponent)")
            } else {
                showError("Failed to start recording.")
                try? audioSession.setActive(false) // Clean up session
            }

        } catch {
            showError("Error setting up recorder: \(error.localizedDescription)")
            try? audioSession.setActive(false) // Clean up session
            isRecording = false // Ensure state is correct
        }
    }

    func stopRecording() {
        guard isRecording else { return }

        audioRecorder?.stop()
        stopLevelTimer()
        isRecording = false

        let audioSession = AVAudioSession.sharedInstance()
        do {
            try audioSession.setActive(false)
            if let url = recordingURL {
               print("Stopped recording. File saved at: \(url.path)")
               // You might want to move the file from temp directory here
            }
            // Reset recorder and URL for next recording
            audioRecorder = nil
            recordingURL = nil
        } catch {
            // Log this error, but it might not be critical for the user
            print("Error deactivating audio session: \(error.localizedDescription)")
        }
    }

    // MARK: - Helper Methods

    private func generateRecordingURL() -> URL {
        let fileManager = FileManager.default
        // Using temporary directory is often better for intermediate files
        let tempDir = fileManager.temporaryDirectory 
        let fileName = "recording-\(UUID().uuidString).m4a"
        return tempDir.appendingPathComponent(fileName)
    }

    private func showError(_ message: String) {
        errorMessage = message
        recordingFailed = true
        print("Error: \(message)")
    }

    // MARK: - Level Metering

    private func startLevelTimer() {
        levelTimer?.invalidate() // Ensure no duplicate timers
        levelTimer = Timer.scheduledTimer(withTimeInterval: levelUpdateInterval, repeats: true) { [weak self] _ in
            guard let self = self, let recorder = self.audioRecorder, self.isRecording else { return }
            recorder.updateMeters()
            // Power ranges from -160 (silence) to 0 (max power)
            let power = recorder.averagePower(forChannel: 0)
            self.audioLevel = self.normalizePower(power)
        }
    }

    private func stopLevelTimer() {
        levelTimer?.invalidate()
        levelTimer = nil
         // Reset level smoothly or instantly when stopped
         DispatchQueue.main.async {
             withAnimation(.easeOut(duration: 0.2)) {
                 self.audioLevel = 0.0
             }
         }
    }

    private func normalizePower(_ power: Float) -> CGFloat {
        // Map dB range to 0.0 - 1.0. Use -60 dB as effective silence for visualization.
        let minDb: Float = -60.0
        // Ensure power is valid (finite and typically negative)
        guard power.isFinite, power < 0 else { return 0.0 }

        // Clamp power to the minimum dB level
        let clampedPower = max(minDb, power)

        // Calculate normalized level (0 = minDb, 1 = 0 dB)
        let normalizedLevel = (clampedPower - minDb) / (-minDb)

        return CGFloat(normalizedLevel)
    }
}

// Optional: Conformance to AVAudioRecorderDelegate for handling recording errors like disk full
// extension AudioRecorderViewModel: AVAudioRecorderDelegate { ... }
