import SwiftUI

struct EqualizerView: View {
    let level: CGFloat // Normalized level 0.0 to 1.0
    let numberOfBars: Int
    let barColor: Color
    let idleHeight: CGFloat = 5.0 // Min height when level is 0 or not recording
    let cornerRadius: CGFloat = 3.0

    var body: some View {
        GeometryReader { geometry in
            let availableHeight = geometry.size.height
            let maxHeight = availableHeight - idleHeight // Max dynamic height

            HStack(alignment: .bottom, spacing: 4) {
                ForEach(0..<numberOfBars, id: \.self) { _ in
                    // Add slight random variation for visual interest
                    let variation = CGFloat.random(in: 0.8...1.0)
                    let barLevel = level * variation
                    let barHeight = max(idleHeight, barLevel * maxHeight + idleHeight)

                    RoundedRectangle(cornerRadius: cornerRadius)
                        .fill(barColor)
                        .frame(height: barHeight)
                        // Animate height changes smoothly
                        .animation(.interpolatingSpring(stiffness: 180, damping: 12), value: barHeight)
                }
            }
            // Center the bars horizontally if needed, or let HStack manage spacing
            .frame(maxWidth: .infinity, maxHeight: .infinity, alignment: .bottom)
        }
    }
}

