    import kotlinx.serialization.Serializable

    @Serializable
    data class SignupData(
        val username: String,
        val email: String,
        val password: String,
        val confirmation: String
    )
    ```

3.  **Create an Extension Function:** This function will take any serializable object and convert it to `Parameters`.
    ```kotlin
    import io.ktor.http.*
    import kotlinx.serialization.*
    import kotlinx.serialization.json.*

    /**
     * Converts a @Serializable object into Ktor Parameters.
     * Assumes the object serializes into a flat JSON object with primitive values.
     * Non-primitive values (objects, arrays) or nulls will be ignored.
     */
    inline fun <reified T : Any> T.toParameters(): Parameters {
        // Use the default Json instance or configure one if needed
        val json = Json { ignoreUnknownKeys = true } // Example configuration

        // Serialize the object to a JsonElement
        val jsonElement = try {
            json.encodeToJsonElement(this) // Uses the default serializer for the reified type T
        } catch (e: SerializationException) {
            throw IllegalArgumentException("Failed to serialize object of type ${T::class.simpleName}", e)
        }

        // Ensure it's a JsonObject
        require(jsonElement is JsonObject) {
            "Cannot convert to Parameters: Object must serialize to a JsonObject. Found ${jsonElement::class.simpleName}"
        }

        // Build the Parameters
        return Parameters.build {
            jsonElement.forEach { (key, value) ->
                // Only include primitive values, convert them to string
                if (value is JsonPrimitive && !value.isString) {
                    append(key, value.content) // Convert numbers/booleans to string
                } else if (value is JsonPrimitive && value.isString) {
                     append(key, value.content) // Append string value directly
                }
                // Optionally handle JsonNull or log warnings for other types (JsonObject, JsonArray)
                // else { println("Warning: Skipping non-primitive/null value for key '$key'") }
            }
        }
    }
    ```

4.  **Use the Extension Function in your Client Code:**
    ```kotlin
    import io.ktor.client.*
    import io.ktor.client.engine.cio.*
    import io.ktor.client.request.forms.*
    import io.ktor.client.statement.*
    import io.ktor.http.*
    import io.ktor.server.application.*
    import kotlinx.coroutines.*
    import kotlinx.serialization.Serializable

    // Assume defaultServer, Application::main, SignupData, and toParameters() are defined as above

    fun main() {
        // Assume server setup: defaultServer(Application::main).start()

        // Create an instance of your data class
        val signupForm = SignupData(
            username = "JetBrains",
            email = "example@jetbrains.com",
            password = "foobar",
            confirmation = "foobar"
        )

        runBlocking {
            val client = HttpClient(CIO)
            try {
                // Use the extension function to create Parameters
                val formParams = signupForm.toParameters()

                val response: HttpResponse = client.submitForm(
                    url = "http://localhost:8080/signup",
                    formParameters = formParams // Use the generated parameters
                )
                println("Status: ${response.status}")
                println("Response Body: ${response.bodyAsText()}")
            } catch (e: Exception) {
                println("Error during request: ${e.message}")
            } finally {
                client.close()
                // Consider stopping the server if started within main
            }
        }
    }
