resource "aws_codebuild_project" "this" {
  name          = "${local.resource_prefix}-build"
  description   = "Builds the Docker image for ${var.service_name}"
  service_role  = aws_iam_role.codebuild_role.arn
  build_timeout = "15" # minutes

  artifacts {
    type = "CODEPIPELINE"
  }

  environment {
    compute_type                = "BUILD_GENERAL1_SMALL"
    image                       = "aws/codebuild/standard:5.0" # Or a newer version
    type                        = "LINUX_CONTAINER"
    privileged_mode             = true # Required for Docker builds
    image_pull_credentials_type = "CODEBUILD"

    environment_variable {
      name  = "AWS_REGION"
      value = local.region
    }
    environment_variable {
      name  = "AWS_ACCOUNT_ID"
      value = local.account_id
    }
    environment_variable {
      name  = "ECR_REPOSITORY_URI"
      value = aws_ecr_repository.this.repository_url
    }
    environment_variable {
      name  = "IMAGE_TAG"
      value = "latest" # Default tag, can be overridden (e.g., by commit ID) in buildspec
    }
    environment_variable {
      name  = "CONTAINER_NAME"
      value = local.resource_prefix
    }
  }

  logs_config {
    cloudwatch_logs {
      group_name  = "/aws/codebuild/${local.resource_prefix}-build"
      stream_name = "build"
      status      = "ENABLED"
    }
  }

  source {
    type            = "CODEPIPELINE"
    # buildspec defines build commands inline, assumes Dockerfile is in repo root
    buildspec = <<-EOF
      version: 0.2

      phases:
        pre_build:
          commands:
            - echo Logging in to Amazon ECR...
            - aws ecr get-login-password --region $AWS_REGION | docker login --username AWS --password-stdin $AWS_ACCOUNT_ID.dkr.ecr.$AWS_REGION.amazonaws.com
            - COMMIT_HASH=$(echo $CODEBUILD_RESOLVED_SOURCE_VERSION | cut -c 1-7)
            - IMAGE_TAG=\${COMMIT_HASH:=\${IMAGE_TAG}} # Use commit hash if available, else default
        build:
          commands:
            - echo Building the Docker image...
            - docker build -t $ECR_REPOSITORY_URI:$IMAGE_TAG .
            - docker tag $ECR_REPOSITORY_URI:$IMAGE_TAG $ECR_REPOSITORY_URI:latest # Also tag as latest
        post_build:
          commands:
            - echo Pushing the Docker image to ECR...
            - docker push $ECR_REPOSITORY_URI:$IMAGE_TAG
            - docker push $ECR_REPOSITORY_URI:latest
            - echo Writing image definitions file...
            # Create the imagedefinitions.json file for ECS deployment action
            - printf '[{"name":"%s","imageUri":"%s"}]' "$CONTAINER_NAME" "$ECR_REPOSITORY_URI:$IMAGE_TAG" > imagedefinitions.json
      artifacts:
        files:
          - imagedefinitions.json
    EOF
  }

  # Required if running CodeBuild within a VPC
  # vpc_config {
  #   vpc_id = var.vpc_id
  #   subnets = var.subnets # Usually private subnets with NAT/VPC Endpoint access
  #   security_group_ids = var.security_groups # SG allowing outbound HTTPS/DockerHub/ECR access
  # }

  tags = var.tags
}

# --- CodePipeline Definition ---
resource "aws_codepipeline" "this" {
  name     = var.pipeline_name
  role_arn = aws_iam_role.codepipeline_role.arn

  artifact_store {
    type     = "S3"
    location = aws_s3_bucket.codepipeline_artifacts.bucket
  }

  # --- Source Stage ---
  stage {
    name = "Source"

    action {
      name             = "Source"
      category         = "Source"
      owner            = var.source_provider == "GitHub" ? "ThirdParty" : "AWS"
      provider         = var.source_provider # "GitHub" or "CodeCommit"
      version          = "1"
      output_artifacts = ["SourceArtifact"]

      configuration = merge(
        var.source_provider == "GitHub" ? {
          Owner                = var.source_repo_owner
          Repo                 = var.source_repo_name
          Branch               = var.source_repo_branch
          PollForSourceChanges = true # Or configure Webhooks
          OAuthToken           = format("{{resolve:secretsmanager:%s:SecretString:token}}", var.github_oauth_token_secret_arn) # Reference SM secret
        } : {},
        var.source_provider == "CodeCommit" ? {
          RepositoryName       = var.source_repo_name
          BranchName           = var.source_repo_branch
          PollForSourceChanges = true
        } : {}
      )
    }
  }

  # --- Build Stage ---
  stage {
    name = "Build"

    action {
      name             = "Build"
      category         = "Build"
      owner            = "AWS"
      provider         = "CodeBuild"
      input_artifacts  = ["SourceArtifact"]
      output_artifacts = ["BuildArtifact"]
      version          = "1"

      configuration = {
        ProjectName = aws_codebuild_project.this.name
      }
    }
  }

  # --- Deploy Stage ---
  stage {
    name = "Deploy"

    action {
      name            = "DeployECS"
      category        = "Deploy"
      owner           = "AWS"
      provider        = "ECS"
      input_artifacts = ["BuildArtifact"] # Contains imagedefinitions.json
      version         = "1"

      configuration = {
        ClusterName = local.cluster_name
        ServiceName = aws_ecs_service.this.name
        # FileName points CodePipeline to the artifact containing the image URI definition
        FileName    = "imagedefinitions.json"
      }
    }
  }

  tags = var.tags
}
