**My Analysis of the Prompt:**

The core requirements are:
1.  **Track Scores:** Point-by-point, game-by-game, set-by-set.
2.  **Match Structure:** Best of 3 sets.
3.  **User Input:** Allow users to indicate who won each point.
4.  **Advanced Mode (Toggleable):**
    *   When ON: Track *how* each point was won (Winner, Unforced Error, Forced Error, Ace, Return Winner, Serve Winner).
    *   When OFF: Just track who won the point.

The crucial part is correctly implementing the tennis scoring rules: points (0, 15, 30, 40, Ad, Game), games, tiebreaks (at 6-6 in a set), sets (first to 6 games win by 2, or 7-6 via tiebreak, or 7-5), and match (first to win 2 sets).

**My Answer:**

```swift
import SwiftUI

// MARK: - Data Models

enum Player: Identifiable {
    case player1
    case player2

    var id: Int { hashValue }

    var name: String {
        switch self {
        case .player1: return "Player 1"
        case .player2: return "Player 2"
        }
    }
}

enum PointType: String, CaseIterable, Identifiable {
    case winner = "Winner"
    case unforcedError = "Unforced Error"
    case forcedError = "Forced Error"
    case ace = "Ace"
    case returnWinner = "Return Winner"
    case serveWinner = "Serve Winner"
    var id: String { self.rawValue }
}

// Stores details of a single recorded point (for history/stats)
struct PointRecord: Identifiable {
    let id = UUID()
    let winningPlayer: Player
    let pointType: PointType? // nil if advanced mode was off
    let setIndex: Int
    let gameScoreP1: Int // Games score at the time
    let gameScoreP2: Int // Games score at the time
    let pointScoreP1: String // Point score (e.g., "15", "40", "Ad") at the time point was won
    let pointScoreP2: String // Point score at the time point was won
    let timestamp = Date()
}

// Manages the state of a single game
class GameState: ObservableObject, Identifiable {
    let id = UUID()
    @Published var scoreP1: Int = 0 // Point index: 0, 1, 2, 3...
    @Published var scoreP2: Int = 0
    @Published var isTiebreak: Bool = false
    @Published var isComplete: Bool = false
    @Published var winner: Player? = nil

    // Converts point index to tennis score string
    private func displayScore(for points: Int) -> String {
        guard !isTiebreak else { return "\(points)" }
        switch points {
        case 0: return "0"
        case 1: return "15"
        case 2: return "30"
        case 3: return "40"
        default: return "Ad" // Handled below for deuce/ad
        }
    }

    // Returns the current score string (e.g., "15-30", "Deuce", "Ad-In")
    var scoreString: String {
        if isComplete { return "Game: \(winner?.name ?? "-")" }
        if isTiebreak { return "\(scoreP1) - \(scoreP2)" }

        if scoreP1 >= 3 && scoreP2 >= 3 {
            if scoreP1 == scoreP2 { return "Deuce" }
            return scoreP1 > scoreP2 ? "Ad - 40" : "40 - Ad" // "Ad-In" / "Ad-Out" relative to P1
        } else {
            return "\(displayScore(for: scoreP1)) - \(displayScore(for: scoreP2))"
        }
    }

    // Returns player-specific score for history recording
    func getScoreString(for player: Player) -> String {
        if isTiebreak {
            return "\(player == .player1 ? scoreP1 : scoreP2)"
        }
        if scoreP1 >= 3 && scoreP2 >= 3 {
             if scoreP1 == scoreP2 { return "Deuce" } // Represent deuce point simply
             let playerPoints = (player == .player1) ? scoreP1 : scoreP2
             let opponentPoints = (player == .player1) ? scoreP2 : scoreP1
             return playerPoints > opponentPoints ? "Ad" : "40"
        }
        return displayScore(for: (player == .player1) ? scoreP1 : scoreP2)
    }


    func addPoint(for player: Player) {
        guard !isComplete else { return }

        if player == .player1 { scoreP1 += 1 } else { scoreP2 += 1 }
        checkGameCompletion()
    }

    private func checkGameCompletion() {
        if isTiebreak {
            if (scoreP1 >= 7 || scoreP2 >= 7) && abs(scoreP1 - scoreP2) >= 2 {
                completeGame(winner: scoreP1 > scoreP2 ? .player1 : .player2)
            }
        } else {
            if (scoreP1 >= 4 || scoreP2 >= 4) && abs(scoreP1 - scoreP2) >= 2 {
                completeGame(winner: scoreP1 > scoreP2 ? .player1 : .player2)
            }
        }
    }

    private func completeGame(winner: Player) {
        self.winner = winner
        self.isComplete = true
    }
}

// Manages the state of a single set
class SetState: ObservableObject, Identifiable {
    let id = UUID()
    @Published var gamesP1: Int = 0
    @Published var gamesP2: Int = 0
    @Published var currentGame: GameState = GameState()
    @Published var completedGames: [GameState] = [] // History within the set
    @Published var isComplete: Bool = false
    @Published var winner: Player? = nil

    var scoreString: String {
        "\(gamesP1) - \(gamesP2)"
    }

    func recordCompletedGame(game: GameState) {
        guard let gameWinner = game.winner else { return }
        if gameWinner == .player1 { gamesP1 += 1 } else { gamesP2 += 1 }
        completedGames.append(game)
        checkSetCompletion()

        if !isComplete {
            startNewGame()
        }
    }

     private func startNewGame() {
         let isNextGameTiebreak = (gamesP1 == 6 && gamesP2 == 6)
         currentGame = GameState()
         currentGame.isTiebreak = isNextGameTiebreak
     }

    private func checkSetCompletion() {
        // Standard win condition (6+ games, win by 2)
        if (gamesP1 >= 6 || gamesP2 >= 6) && abs(gamesP1 - gamesP2) >= 2 {
            completeSet(winner: gamesP1 > gamesP2 ? .player1 : .player2)
        }
        // Tiebreak win condition (7-6 or 6-7)
        else if (gamesP1 == 7 && gamesP2 == 6) || (gamesP2 == 7 && gamesP1 == 6) {
             completeSet(winner: gamesP1 > gamesP2 ? .player1 : .player2)
        }
    }

    private func completeSet(winner: Player) {
        self.winner = winner
        self.isComplete = true
    }
}

// Main ViewModel for the Match
class MatchViewModel: ObservableObject {
    @Published var sets: [SetState] = [SetState()]
    @Published var currentSetIndex: Int = 0
    @Published var matchComplete: Bool = false
    @Published var matchWinner: Player? = nil

    @Published var isAdvancedMode: Bool = false
    @Published var pointHistory: [PointRecord] = []
    @Published var selectedPointType: PointType = .winner // Default for advanced mode

    var currentSet: SetState { sets[currentSetIndex] }
    var currentGame: GameState { currentSet.currentGame }

    var setScores: [(p1: Int, p2: Int)] {
        sets.map { ($0.gamesP1, $0.gamesP2) }
    }

    func scorePoint(for player: Player) {
        guard !matchComplete else { return }

        // Record point before updating score
        let pointDetail = isAdvancedMode ? selectedPointType : nil
        let record = PointRecord(
            winningPlayer: player,
            pointType: pointDetail,
            setIndex: currentSetIndex,
            gameScoreP1: currentSet.gamesP1,
            gameScoreP2: currentSet.gamesP2,
            pointScoreP1: currentGame.getScoreString(for: .player1),
            pointScoreP2: currentGame.getScoreString(for: .player2),
            timestamp: Date()
        )
        if isAdvancedMode {
            pointHistory.append(record)
        }

        // Add point to current game
        currentGame.addPoint(for: player)

        // Check if game finished
        if currentGame.isComplete {
            currentSet.recordCompletedGame(game: currentGame)

            // Check if set finished
            if currentSet.isComplete {
                checkMatchCompletion()
                // If match not over, start next set (if needed)
                if !matchComplete && currentSetIndex < 2 { // Max 3 sets (indices 0, 1, 2)
                    currentSetIndex += 1
                    if sets.count <= currentSetIndex {
                        sets.append(SetState()) // Add a new set object if needed
                    }
                }
            }
        }
    }

    private func checkMatchCompletion() {
        let setsWonP1 = sets.filter { $0.isComplete && $0.winner == .player1 }.count
        let setsWonP2 = sets.filter { $0.isComplete && $0.winner == .player2 }.count

        // Best of 3 sets
        if setsWonP1 >= 2 || setsWonP2 >= 2 {
            matchComplete = true
            matchWinner = setsWonP1 > setsWonP2 ? .player1 : .player2
        }
    }

    func resetMatch() {
        sets = [SetState()]
        currentSetIndex = 0
        matchComplete = false
        matchWinner = nil
        isAdvancedMode = false
        pointHistory = []
        selectedPointType = .winner
    }
}


