class GameState: ObservableObject, Identifiable {
    let id = UUID()
    @Published var pointsPlayer1: Int = 0
    @Published var pointsPlayer2: Int = 0
    @Published var gameWinner: Player? = nil
    let isTiebreak: Bool

    init(isTiebreak: Bool = false) {
        self.isTiebreak = isTiebreak
    }

