        } else {
            // Standard tennis scoring display logic
            switch (pointsPlayer1, pointsPlayer2) {
            case (0, 0): return "0 - 0" // Using numbers for simplicity, could map to Love, 15 etc.
            case (1, 0): return "15 - 0"
            case (0, 1): return "0 - 15"
            case (2, 0): return "30 - 0"
            case (0, 2): return "0 - 30"
            case (3, 0): return "40 - 0"
            case (0, 3): return "0 - 40"
            case (1, 1): return "15 - 15"
            case (2, 1): return "30 - 15"
            case (1, 2): return "15 - 30"
            case (3, 1): return "40 - 15"
            case (1, 3): return "15 - 40"
            case (2, 2): return "30 - 30"
            case (3, 2): return "40 - 30"
            case (2, 3): return "30 - 40"
            case (3, 3): return "Deuce"
            case (let p1, let p2) where p1 >= 3 && p2 >= 3:
                if p1 == p2 { return "Deuce" }
                return p1 > p2 ? "Ad - In" : "Ad - Out" // Ad P1 or Ad P2
            default: return "\(pointsPlayer1) - \(pointsPlayer2)" // Fallback
            }
        }
    }

    // Returns true if the game is now complete
    @discardableResult
    func addPoint(player: Player) -> Bool {
        guard gameWinner == nil else { return false } // Game already finished

        if player == .player1 { pointsPlayer1 += 1 }
        else { pointsPlayer2 += 1 }

        checkGameCompletion()
        return gameWinner != nil
    }

    private func checkGameCompletion() {
        if isTiebreak {
            if (pointsPlayer1 >= 7 || pointsPlayer2 >= 7) && abs(pointsPlayer1 - pointsPlayer2) >= 2 {
                gameWinner = (pointsPlayer1 > pointsPlayer2) ? .player1 : .player2
            }
        } else {
            if (pointsPlayer1 >= 4 || pointsPlayer2 >= 4) && abs(pointsPlayer1 - pointsPlayer2) >= 2 {
                gameWinner = (pointsPlayer1 > pointsPlayer2) ? .player1 : .player2
            }
        }
    }
}

// Represents the state of a single Set
class SetState: ObservableObject, Identifiable {
    let id = UUID()
    @Published var gamesPlayer1: Int = 0
    @Published var gamesPlayer2: Int = 0
    @Published var currentGame: GameState = GameState()
    @Published var completedGames: [GameState] = [] // History within the set
    @Published var setWinner: Player? = nil
    @Published var isTiebreakActive: Bool = false

    var isComplete: Bool { setWinner != nil }

    // Call when a game is finished, returns true if set is now complete
    @discardableResult
    func addGame(winner: Player) -> Bool {
        guard setWinner == nil else { return false }

        // Store completed game
        completedGames.append(currentGame)

        if winner == .player1 { gamesPlayer1 += 1 }
        else { gamesPlayer2 += 1 }

        checkSetCompletion()

        // Start new game if set is not yet complete
        if !isComplete {
            isTiebreakActive = (gamesPlayer1 == 6 && gamesPlayer2 == 6)
            currentGame = GameState(isTiebreak: isTiebreakActive)
        }
        return isComplete
    }

    private func checkSetCompletion() {
        // Standard set win conditions (including tiebreak win)
        if (gamesPlayer1 == 6 && gamesPlayer2 <= 4) || (gamesPlayer1 == 7 && gamesPlayer2 == 5) {
            setWinner = .player1
        } else if (gamesPlayer2 == 6 && gamesPlayer1 <= 4) || (gamesPlayer2 == 7 && gamesPlayer1 == 5) {
            setWinner = .player2
        } else if gamesPlayer1 == 7 && gamesPlayer2 == 6 { // Won tiebreak
            setWinner = .player1
        } else if gamesPlayer2 == 7 && gamesPlayer1 == 6 { // Won tiebreak
            setWinner = .player2
        }
    }
}

// Overall Match State - Main Observable Object
class MatchState: ObservableObject {
    @Published var sets: [SetState] = [SetState()]
    @Published var currentSetIndex: Int = 0
    @Published var matchWinner: Player? = nil
    @Published var isAdvancedTrackingEnabled: Bool = false
    @Published var pointHistory: [PointDetail] = []

    var currentSet: SetState { sets[currentSetIndex] }
    var currentGame: GameState { currentSet.currentGame }

    var player1SetsWon: Int { sets.filter { $0.setWinner == .player1 }.count }
    var player2SetsWon: Int { sets.filter { $0.setWinner == .player2 }.count }

    // Adds a point for the specified player
    func addPoint(player: Player, pointType: PointType) {
        guard matchWinner == nil else { return } // Match already finished

        // Record point detail if advanced tracking is on
        if isAdvancedTrackingEnabled {
            pointHistory.append(PointDetail(winningPlayer: player, pointType: pointType))
        }

        // Add point to the current game
        let gameFinished = currentGame.addPoint(player: player)

        // If game finished, update set score
        if gameFinished, let gameWinner = currentGame.gameWinner {
            let setFinished = currentSet.addGame(winner: gameWinner)

            // If set finished, check match score
            if setFinished {
                checkMatchCompletion()
                // If match not finished, start next set (if applicable)
                if matchWinner == nil && currentSetIndex < 2 { // Max 3 sets
                    currentSetIndex += 1
                    // Ensure the sets array has the next set object
                    if currentSetIndex == sets.count {
                       sets.append(SetState())
                    }
                }
            }
        }
    }

    private func checkMatchCompletion() {
        if player1SetsWon >= 2 {
            matchWinner = .player1
        } else if player2SetsWon >= 2 {
            matchWinner = .player2
        }
        // Tiebreak set at 2-2 is not handled here, assuming standard best-of-3
    }

    func resetMatch() {
        sets = [SetState()]
        currentSetIndex = 0
        matchWinner = nil
        isAdvancedTrackingEnabled = false
        pointHistory = []
    }
}

