        // Preserve the existing velocity component along the normal direction
        Vector3 currentNormalVelocity = Vector3.Project(rb.velocity, currentSurfaceNormal);
        rb.velocity = targetVelocity + currentNormalVelocity;

        // Alternative simpler velocity set (might feel less physically correct on steep slopes):
        // rb.velocity = targetVelocity;
    }

