        function bringToFront(winElement) {
             if (parseInt(winElement.style.zIndex) !== zIndexCounter) {
                winElement.style.zIndex = ++zIndexCounter;
             }
        }

        function addEventlisteners(win, id, title) {
            const closeBtn = win.querySelector('.window-close-btn');
            closeBtn.onclick = () => closeWindow(id);
        }

        // --- Taskbar Management ---
        function createTaskbarIcon(id, title, winElement) {
             const icon = document.createElement('div');
             icon.id = `taskbar-${id}`;
             icon.className = 'taskbar-icon';
             icon.textContent = title;
             icon.title = title;
             icon.onclick = () => bringToFront(winElement);
             taskbar.appendChild(icon);
