        function removeTaskbarIcon(id) {
             const icon = document.getElementById(`taskbar-${id}`);
             if (icon) {
                 icon.remove();
             }
        }

        // --- Dragging Logic ---
        function makeDraggable(element) {
            const header = element.querySelector('.window-header');
            let offsetX, offsetY, isDragging = false;

            header.addEventListener('mousedown', (e) => {
                // Only drag with left mouse button
                if (e.button !== 0) return;

                isDragging = true;
                element.classList.add('dragging');
                bringToFront(element); // Bring to front when starting drag

                offsetX = e.clientX - element.offsetLeft;
                offsetY = e.clientY - element.offsetTop;

                // Use capturing to ensure mouseup is caught even if mouse leaves window
                document.addEventListener('mousemove', onMouseMove, true);
                document.addEventListener('mouseup', onMouseUp, true);
            });

            function onMouseMove(e) {
                if (!isDragging) return;

                // Constrain window position to viewport
                let newX = e.clientX - offsetX;
                let newY = e.clientY - offsetY;
                const desktopRect = desktop.getBoundingClientRect();
                const taskbarHeight = taskbar.offsetHeight;

                // Basic boundary check (can be improved)
                newX = Math.max(0, Math.min(newX, desktopRect.width - element.offsetWidth));
                newY = Math.max(0, Math.min(newY, desktopRect.height - element.offsetHeight)); // Adjusted for taskbar


                element.style.left = `${newX}px`;
                element.style.top = `${newY}px`;
            }

            function onMouseUp(e) {
                 if (e.button !== 0 || !isDragging) return; // Only react to left button mouseup
                 isDragging = false;
                 element.classList.remove('dragging');
                 document.removeEventListener('mousemove', onMouseMove, true);
                 document.removeEventListener('mouseup', onMouseUp, true);
            }
