                    const textContent = data && data.content ? data.content : "";
                    content = `<textarea id="notepad-textarea" spellcheck="false">${textContent}</textarea>`;
                    width = 500;
                    height = 400;
                    createWindow(appId, title, content, width, height);
                    break;
                default:
                    console.warn(`App "${appName}" not recognized.`);
            }
        }

        function generateFileExplorerContent(currentDir, path = []) {
            let listHtml = '<div class="file-explorer-list">';
            // Could add ".." for navigating up later
            for (const name in currentDir) {
                const item = currentDir[name];
                const fullPath = [...path, name];
                if (item.type === "folder") {
                    // Basic: Just show folder name (could make clickable to navigate)
                    listHtml += `<div>📁 ${name}</div>`;
                } else if (item.type === "file") {
                    // Make files clickable to open in Notepad
                    listHtml += `<div data-filename="${name}" data-content="${escape(item.content)}">📄 ${name}</div>`;
                }
            }
            listHtml += '</div>';
            return listHtml;
        }

        // --- Event Listeners ---
        desktop.addEventListener('dblclick', (e) => {
             // Handle desktop icon double clicks
             const icon = e.target.closest('.desktop-icon');
             if (icon && icon.dataset.app) {
                 openApp(icon.dataset.app);
