            if (ok) {
                // Check overflow
                bool checkOk;
                qint64 longVal = strVal.toLongLong(&checkOk, 10);
                if (checkOk && longVal >= INT_MIN && longVal <= INT_MAX && longVal == result) {
                     // It's a valid integer string like "42"
