 * @return True if the cell contains one of the allowed numbers, false otherwise.
 */
bool checkExcelCell(const QString &filePath, const QString &cellAddress) {
    // Load the Excel document
    QXlsx::Document xlsxDoc(filePath);
    if (!xlsxDoc.load()) {
        qWarning() << "Error: Could not load Excel file:" << filePath;
        return false;
    }

    // Read the cell value
    // Using read() is convenient, handles different underlying cell types.
    QVariant cellValue = xlsxDoc.read(cellAddress);

    // Check if cell is empty or invalid address
    if (!cellValue.isValid() || cellValue.isNull()) {
        qWarning() << "Warning: Cell" << cellAddress << "in file" << filePath << "is empty or invalid.";
        return false;
    }

    int parsedNumber;
    if (parseCellValueToInt(cellValue, parsedNumber)) {
        // Successfully parsed an integer, check if it's in the allowed set
        if (ALLOWED_NUMBERS.contains(parsedNumber)) {
            qDebug() << "Cell" << cellAddress << "value (" << cellValue.toString() << ") parsed to" << parsedNumber << "- Accepted.";
            return true;
        } else {
            qDebug() << "Cell" << cellAddress << "value (" << cellValue.toString() << ") parsed to" << parsedNumber << "- Rejected (not in allowed set).";
            return false;
        }
    } else {
        // Value could not be parsed as a valid integer representation according to the rules
        qDebug() << "Cell" << cellAddress << "value (" << cellValue.toString() << ") - Rejected (could not parse as a valid integer).";
        return false;
    }
}

