// std::atomic<int> i; 
// std::atomic<int> x; 

// Function to atomically increment i if i < x
// Returns true if the increment happened, false otherwise.
bool atomic_increment_if_less(std::atomic<int>& i, const std::atomic<int>& x) {
    // Start by loading the current value of i. 
    // Using memory_order_relaxed is often sufficient here, as the 
    // compare_exchange operation itself will provide necessary synchronization.
    int current_i = i.load(std::memory_order_relaxed); 

    while (true) {
        // Load the current value of the boundary x inside the loop,
        // as it might change concurrently.
        int current_x = x.load(std::memory_order_relaxed);

        // Check the condition: if i is not less than x, we stop trying.
        if (current_i >= current_x) {
            return false; // Condition not met, no increment performed.
        }

        // If the condition is met, prepare the desired value.
        int desired_i = current_i + 1;

        // Attempt the atomic compare-and-swap.
        // This operation atomically compares the value of 'i' with 'current_i'.
        // - If they are equal, 'i' is updated to 'desired_i', and the function returns true.
        // - If they are not equal (meaning another thread modified 'i' since we loaded it),
        //   the function returns false, and 'current_i' is updated with the new value of 'i'.
        // We use compare_exchange_weak because it can be more performant on some architectures,
        // even though it might fail spuriously (hence the loop).
        if (i.compare_exchange_weak(current_i, desired_i,
                                    std::memory_order_release,  // Memory order on success
                                    std::memory_order_relaxed)) // Memory order on failure
        {
            // Increment was successful.
            return true; 
        }

        // If compare_exchange_weak failed:
        // 'current_i' now holds the more recent value of 'i'.
        // The loop will continue, load 'x' again, re-check the condition 
        // with the updated 'current_i', and retry the compare-exchange.
    }
}

