public static class HashSetSerializer
{
    // Serializes the HashSet<string> to a byte array.
    public static byte[] SerializeToBytes(HashSet<string> hashSet)
    {
        if (hashSet == null)
        {
            throw new ArgumentNullException(nameof(hashSet));
        }

        using (var memoryStream = new MemoryStream())
        {
            // Use BinaryWriter for efficient writing of primitives and strings.
            // Using UTF8 encoding by default for strings.
            using (var writer = new BinaryWriter(memoryStream, Encoding.UTF8, leaveOpen: true))
            {
