                {
                    writer.Write(item);
                }
            } // BinaryWriter is disposed here, but memoryStream remains open

            // Return the underlying byte array.
            return memoryStream.ToArray();
        }
    }

    // Deserializes a byte array back into a HashSet<string>.
    public static HashSet<string> DeserializeFromBytes(byte[] data)
    {
        if (data == null)
        {
            throw new ArgumentNullException(nameof(data));
        }

        var hashSet = new HashSet<string>();

        using (var memoryStream = new MemoryStream(data))
        {
            // Use BinaryReader to read the data back.
            // Ensure the same encoding (UTF8) is used.
            using (var reader = new BinaryReader(memoryStream, Encoding.UTF8))
            {
                // 1. Read the number of elements.
