                // Initialize HashSet with capacity for potential performance improvement
                hashSet = new HashSet<string>(count);

                // 2. Read each string element.
                // BinaryReader.ReadString() reads the length prefix and then the string bytes.
                for (int i = 0; i < count; i++)
                {
                    hashSet.Add(reader.ReadString());
                }
            }
        }

        return hashSet;
    }
}

