/* client.zig */
const std = @import("std");
const rl = @import("raylib");
const net = std.net;
const posix = std.posix;
const mem = std.mem;

const ControllerEvents = enum(i16) {
    ANALOG_LX = 0, ANALOG_LY = 1, ANALOG_RX = 2, ANALOG_RY = 3,
    L1 = 4, L2 = 5, R1 = 6, R2 = 7,
    TRIANGLE = 8, CROSS = 9, SQUARE = 10, CIRCLE = 11,
    UP = 12, DOWN = 13, LEFT = 14, RIGHT = 15,
    SELECT = 16, START = 17,

    const count = @typeInfo(ControllerEvents).Enum.fields.len;
};

// Packed struct matching C server's event_pair
const EventPair = packed struct {
    index: i16, // Assumes native endian matches server
    value: i16, // Assumes native endian matches server
};

// Send an array of EventPair structures
fn sendControllerEvents(
    sock: posix.fd_t,
    addr: *const net.Address,
    eventPairs: []const EventPair,
) !void {
    const sockaddr = addr.any; // Get the generic sockaddr
    const addrlen = addr.getOsSockLen();
    const bytesToSend = mem.sliceAsBytes(eventPairs); // Get byte slice

    const bytes_sent = try posix.sendto(sock, bytesToSend, 0, &sockaddr, addrlen);
    if (bytes_sent != bytesToSend.len) {
        std.log.warn("Partial send: Expected {d} bytes, sent {d} bytes.", .{ bytesToSend.len, bytes_sent });
    }
}

// Create a UDP socket for sending
fn createUDPSocket() !posix.fd_t {
    return posix.socket(posix.AF.INET, posix.SOCK.DGRAM, 0);
}

// Initialize controller state array (values only)
fn initializeControllerState() [ControllerEvents.count]i16 {
    var controllerState: [ControllerEvents.count]i16 = undefined;
    @memset(&controllerState, 0); // Zero initialize
    return controllerState;
}

