    const sock = try createUDPSocket();
    defer posix.close(sock);

    const serverAddr = try net.Address.parseIp4("127.0.0.1", 31415);
    std.debug.print("Client sending to 127.0.0.1:{d}\n", .{serverAddr.getPort()});

