// Disjoint Set Union (DSU) structure
// Uses path compression for find operation. Union is basic.
struct DSU {
    std::vector<int> parent;
    // Constructor initializes each element as its own parent (separate component)
    DSU(int n) {
        parent.resize(n + 1); // Use 1-based indexing for houses
        std::iota(parent.begin(), parent.end(), 0); // parent[i] = i for i=0..n
    }

    // Finds the representative (root) of the set containing element i
    // Applies path compression for optimization.
    int find(int i) {
        if (parent[i] == i)
            return i;
        // Path compression: make node point directly to root
        return parent[i] = find(parent[i]);
    }

    // Unites the sets containing elements i and j
    void unite(int i, int j) {
        int root_i = find(i);
        int root_j = find(j);
        // If they are already in the same set, do nothing
        if (root_i != root_j) {
            // Make the root of j's set point to the root of i's set
            parent[root_j] = root_i;
        }
    }
};

