        min_price.resize(n);
        min_price_node_idx.resize(n);
        for (int i = 0; i < n; ++i) {
            min_price[i] = prices[i];           // Initial min price is the node's own price
            min_price_node_idx[i] = i;          // Initial min price node is the node itself
        }
    }

    // Finds the representative (root) of the set containing element i, with path compression
    int find(int i) {
        if (parent[i] == i)
            return i;
        return parent[i] = find(parent[i]); // Path compression
    }

    // Unites the sets containing elements i and j
    void unite(int i, int j) {
        int root_i = find(i);
        int root_j = find(j);
        if (root_i != root_j) {
            // Decide which root becomes the parent based on the minimum price in the component.
            // If prices are equal, we can optionally use the node index as a tie-breaker,
            // though it doesn't affect the total minimum cost. Here, we prefer the component
            // whose minimum price node has a smaller index in case of a tie in prices.
            bool j_is_better = (min_price[root_j] < min_price[root_i]) ||
                               (min_price[root_j] == min_price[root_i] && min_price_node_idx[root_j] < min_price_node_idx[root_i]);

            if (j_is_better) {
                // Make root_j the new root of the combined set
                parent[root_i] = root_j;
                // The minimum price information is already correctly stored in root_j
            } else {
                // Make root_i the new root of the combined set
                parent[root_j] = root_i;
                // The minimum price information is already correctly stored in root_i
            }
            // Standard union-by-rank or union-by-size could be added for performance optimization,
            // but is not strictly required for correctness here.
        }
    }
};

