/**
 * Defines a result type that represents either a successful outcome
 * with a value or an error outcome with an error object.
 * @template T The type of the value in case of success.
 * @template E The type of the error in case of failure (defaults to unknown).
 */
export type Result<T, E = unknown> =
  | { success: true; value: T }
  | { success: false; error: E };

/**
 * Wraps a potentially throwing function (synchronous or asynchronous)
 * in a try/catch block and returns a Promise resolving to a Result object.
 *
 * This function normalizes the behavior by always returning a Promise,
 * regardless of whether the input function is sync or async.
 *
 * @template A The type of the arguments tuple for the function fn.
 * @template R The type of the return value (or Promise-resolved value) of the function fn.
 * @param fn The function to wrap. Can be synchronous or asynchronous (return a Promise).
 * @returns A new function that takes the same arguments as fn, but returns
 *          a Promise resolving to a Result<Awaited<R>>.
 */
export function tryWrap<A extends any[], R>(
  fn: (...args: A) => R | Promise<R> // Accepts sync or async
): (...args: A) => Promise<Result<Awaited<R>>> { // Always returns Promise<Result>
  return async (...args: A): Promise<Result<Awaited<R>>> => {
    try {
      // Await works for both Promises and non-Promise values.
      const value = await fn(...args);
      return { success: true, value };
    } catch (error) {
      // The caught error is of type 'unknown'.
      return { success: false, error };
    }
  };
}

