<?php

use Carbon\Carbon;

/**
 * Calculates the start and end dates for a sequence of processes.
 *
 * The start date of the first process is the order created date.
 * The end date of a process is calculated by adding completed days (interpreted as business days/weekdays)
 * to its start date.
 * The start date of subsequent processes is the end date of the previous process.
 * Processes are sorted by their 'sequence' key before calculation.
 *
 * @param string $orderCreatedDate The initial date string (format: 'd/m/Y h:i A').
 * @param array $processes An array of processes, each containing 'sequence' and 'completed_days'.
 *                         The 'start_date' and 'end_date' keys will be added/overwritten.
 * @return array The processes array with calculated 'start_date' and 'end_date'.
 * @throws \Carbon\Exceptions\InvalidFormatException If the date format is incorrect.
 */
function calculateProcessDates(string $orderCreatedDate, array $processes): array
{
    // Ensure Carbon is available
    if (!class_exists(Carbon::class)) {
        // Handle error: Carbon library not found.
        // In a Laravel context, this is usually available via Composer.
        throw new \Exception("Carbon library is required but not found.");
    }

    // 1. Parse the initial order created date.
    // Ensure the format matches the input string.
    try {
        $currentProcessStartDate = Carbon::createFromFormat('d/m/Y h:i A', $orderCreatedDate);
    } catch (\Carbon\Exceptions\InvalidFormatException $e) {
        // Handle invalid date format error
        throw new \Carbon\Exceptions\InvalidFormatException("Invalid date format for orderCreatedDate. Expected 'd/m/Y h:i A'.");
    }


    // 2. Sort processes by sequence to ensure correct calculation order.
    usort($processes, function ($a, $b) {
        // Check if 'sequence' key exists, default to 0 if not
        $seqA = $a['sequence'] ?? 0;
        $seqB = $b['sequence'] ?? 0;
        return $seqA <=> $seqB;
    });

    // 3. Iterate through the sorted processes and calculate dates.
    foreach ($processes as $index => &$process) { // Use reference to modify the original array
        // Validate required keys
        if (!isset($process['completed_days'])) {
            // Handle missing key error - maybe skip this process or throw an error
             trigger_error("Process at index {$index} is missing 'completed_days' key.", E_USER_WARNING);
             // Optionally set default dates or skip
             $process['start_date'] = 'Error: Missing completed_days';
             $process['end_date'] = 'Error: Missing completed_days';
             // If we set an error and continue, the next process might rely on a valid end date.
             // It might be better to throw an exception or stop processing.
             // For this example, we'll just set error strings and let the loop continue,
             // potentially causing issues for the next process if it tries to use the end date.
             // A safer approach would be to break or throw an exception.
             continue; // Move to the next process
        }

        // Set the start date for the current process
        // For the first process, $currentProcessStartDate is the initial order date.
        // For subsequent processes, it's the end date of the previous one.
        $process['start_date'] = $currentProcessStartDate->format('d/m/Y h:i A');

        // Calculate the end date by adding 'completed_days'.
        // IMPORTANT: Based on the user's example output (27/06 + 4 days -> 03/07),
        // it seems 'completed_days' should be interpreted as *business days* (weekdays).
        // If calendar days are intended, use ->addDays() instead of ->addWeekdays().
        $endDate = $currentProcessStartDate->copy()->addWeekdays($process['completed_days']);
        $process['end_date'] = $endDate->format('d/m/Y h:i A');

        // Update the start date for the *next* process
        $currentProcessStartDate = $endDate;
    }
    // Unset the reference to avoid potential issues later
    unset($process);

    // 4. Return the updated processes array.
    return $processes;
}

// --- Example Usage ---
