    return new static(
      $configuration,
      $plugin_id,
      $plugin_definition,
      $container->get('entity_type.manager'),
      $container->get('current_user')
    );
  }

  /**
   * {@inheritdoc}
   */
  public function build() {
    $build = [];
    $tag_name = 'foobar';
    // NOTE: Assumes the taxonomy reference field on 'article' nodes is 'field_tags'.
    $field_name = 'field_tags';
    // NOTE: Assumes the vocabulary containing the tag is 'tags'. Add this for robustness.
    $vocabulary_id = 'tags';
    $limit = 10; // Number of items to display

    // 1. Load the taxonomy term more robustly.
    $term_storage = $this->entityTypeManager->getStorage('taxonomy_term');
    $terms = $term_storage->loadByProperties([
      'name' => $tag_name,
      'vid' => $vocabulary_id, // Recommended: Be specific about the vocabulary
    ]);

    if (empty($terms)) {
      // Optionally log this situation.
      // Return an empty build or a message. For a block, often empty is better.
      return [];
      // Or: return ['#markup' => $this->t('No articles found matching the tag.')];
    }
    // If multiple terms match (e.g., same name in same vocab?), use the first.
    $term = reset($terms);
    $term_id = $term->id();

    // 2. Build the entity query.
    $node_storage = $this->entityTypeManager->getStorage('node');
    $query = $node_storage->getQuery()
      ->condition('type', 'article')
      ->condition('status', 1) // Only published nodes
      ->condition($field_name . '.target_id', $term_id)
      ->sort('created', 'DESC') // Most recent first
      ->range(0, $limit) // Limit the results for performance
      ->accessCheck(TRUE); // Ensure user access checks are performed

