// Example using std::os::fd::AsFd/FromRawFd/OwnedFd (Rust 1.63+/1.66+) on Unix-like
use std::os::fd::{AsFd, FromRawFd, OwnedFd};
// For Windows: use std::os::windows::io::{AsSocket, FromRawSocket, OwnedSocket}
use socket2::Socket;
use tokio::net::UdpSocket;
use std::time::Duration;
use std::io;

trait SockOpt {
    fn read_timeout(&self) -> io::Result<Option<Duration>>;
    fn set_read_timeout(&self, duration: Option<Duration>) -> io::Result<()>;
}

impl SockOpt for tokio::net::UdpSocket {
     fn read_timeout(&self) -> io::Result<Option<Duration>> {
         let owned_fd = self.as_fd().try_clone_to_owned().map_err(|e| io::Error::new(io::ErrorKind::Other, e))?;
         // SAFETY: owned_fd is a valid, owned file descriptor.
         // Socket::from_raw_fd takes ownership from owned_fd.into_raw_fd().
         let sock2_sock = unsafe { Socket::from_raw_fd(owned_fd.into_raw_fd()) };
         // sock2_sock will close the duplicated fd when dropped, which is fine.
         sock2_sock.read_timeout()
     }

     fn set_read_timeout(&self, duration: Option<Duration>) -> io::Result<()> {
         let owned_fd = self.as_fd().try_clone_to_owned().map_err(|e| io::Error::new(io::ErrorKind::Other, e))?;
         // SAFETY: See above.
         let sock2_sock = unsafe { Socket::from_raw_fd(owned_fd.into_raw_fd()) };
         let res = sock2_sock.set_read_timeout(duration);
         // sock2_sock will close the duplicated fd when dropped.
         res
     }
}
```
*   **Pros:** Avoids `mem::forget`, keeps original FD safe.
*   **Cons:** Involves system calls (`dup` or `DuplicateHandle`), requires platform-specific handling or newer Rust standard library features/external crates. Requires `unsafe`.

**Conclusion:**

The error arises from misuse of `Socket::from_raw_fd` which takes ownership and closes the descriptor. The recommended solution is to create and configure the socket using `socket2` *before* converting it to a `tokio` socket (Solution 2). If modifying the existing structure is necessary, duplicating the descriptor (Solution 3) is safer than using `mem::forget` (Solution 1).

