  }

  /**
   * Subscribes a callback function to a specific event name.
   * @param {string} eventName - The name of the event to subscribe to.
   * @param {Function} callback - The function to execute when the event is triggered.
   */
  subscribe(eventName, callback) {
    // Basic validation
    if (typeof eventName !== 'string' || eventName.trim() === '') {
      console.error("Events::subscribe requires a non-empty string for eventName.");
      return;
    }
    if (typeof callback !== 'function') {
      console.error("Events::subscribe requires a function for callback.");
      return;
    }

    // If the event doesn't exist in our map, initialize it with an empty array
    if (!this.#subscribers[eventName]) {
      this.#subscribers[eventName] = [];
    }

    // Add the callback to the list for this event, avoiding duplicates if desired (optional)
    // if (!this.#subscribers[eventName].includes(callback)) {
       this.#subscribers[eventName].push(callback);
    // }
  }

  /**
   * Unsubscribes a callback function from a specific event name.
   * @param {string} eventName - The name of the event to unsubscribe from.
   * @param {Function} callback - The specific callback function to remove.
   */
  unsubscribe(eventName, callback) {
    // Basic validation
     if (typeof eventName !== 'string' || eventName.trim() === '') {
      console.error("Events::unsubscribe requires a non-empty string for eventName.");
      return;
    }
     if (typeof callback !== 'function') {
      console.error("Events::unsubscribe requires a function for callback.");
      return;
    }

    const subscribers = this.#subscribers[eventName];

    // Check if the event and subscribers exist
    if (subscribers) {
      // Find the index of the callback
      const index = subscribers.indexOf(callback);
      // If the callback is found, remove it using splice
      if (index !== -1) {
        subscribers.splice(index, 1);
      }
      // Optional: clean up the event name key if no subscribers remain
      // if (subscribers.length === 0) {
      //   delete this.#subscribers[eventName];
      // }
    }
  }

  /**
   * Triggers one or more events, executing subscribed callbacks with provided options.
   * @param {string | string[]} eventNames - The name(s) of the event(s) to trigger.
   * @param {...any} options - Additional arguments to pass to the callbacks.
   */
  trigger(eventNames, ...options) {
    // Normalize eventNames input to always be an array
    const eventsToTrigger = Array.isArray(eventNames) ? eventNames : [eventNames];

    eventsToTrigger.forEach(eventName => {
       if (typeof eventName !== 'string' || eventName.trim() === '') {
        console.warn(`Skipping trigger for invalid event name: ${eventName}`);
        return; // Continue to the next eventName in the forEach loop
      }

      const subscribers = this.#subscribers[eventName];

      // Check if there are any subscribers for this event
      if (subscribers && subscribers.length > 0) {
        // Iterate over a *copy* of the subscribers array using spread syntax ([...subscribers])
        // This prevents issues if a callback calls subscribe/unsubscribe during its execution
        [...subscribers].forEach(callback => {
          try {
            // Execute the callback, passing the options
            callback(...options);
          } catch (error) {
            // Log errors from callbacks but don't let them stop other callbacks
            console.error(`Error in callback for event "${eventName}":`, error);
          }
        });
      }
    });
  }
}

