    <script>
        document.addEventListener('DOMContentLoaded', function () {
            const form = document.getElementById('registerForm');
            const steps = Array.from(form.querySelectorAll('.form-step'));
            const submitBtn = document.getElementById('submitBtn');
            let currentStepIndex = 0;

            function updateStepUI() {
                steps.forEach((step, index) => {
                    const isActive = index === currentStepIndex;
                    const input = step.querySelector('input');
                    const nextBtn = step.querySelector('.next-btn');
                    const prevBtn = step.querySelector('.prev-btn');
                     const stepSubmitBtn = step.querySelector('button[type="submit"]'); // Check if current step has submit

                    step.classList.toggle('active-step', isActive);

                    if (input) {
                        input.disabled = !isActive; // Enable input only if it's the active step
                        if (isActive) {
                           input.focus(); // Auto-focus on the active field
                        }
                    }

                    // Enable submit button only on the last step *after* its input is potentially validated (on 'Next' click logic)
                    if (submitBtn) { // Check if the main submit button exists
                         submitBtn.disabled = true; // Keep disabled unless explicitly enabled later
                    }
                     if (stepSubmitBtn && isActive) { // Enable submit if it's IN the current active step
                         stepSubmitBtn.disabled = false; // Or handle validation before enabling
                    }

                });
                 // Specific check for enabling the final submit button when the *last* step becomes active
                if (currentStepIndex === steps.length - 1) {
                     const lastInput = steps[currentStepIndex].querySelector('input');
                     // Enable submit ONLY if last step is active AND its input is valid (simplistic check here)
                     if (lastInput && lastInput.value && lastInput.checkValidity()) {
                         submitBtn.disabled = false;
                     } else {
                        submitBtn.disabled = true; // Keep disabled if input not valid yet
                     }
                } else {
                    submitBtn.disabled = true; // Disable if not last step
                }
            }

            function validateCurrentStep() {
                const currentStepElement = steps[currentStepIndex];
                const input = currentStepElement.querySelector('input');
                const validator = $(form).validate(); // Get jQuery validator instance

                if (input) {
                    // Trigger validation specifically for the current input
                    validator.element(`#${input.id}`);
                     // Check if the element is valid according to jQuery Validation
                     return validator.valid() || $(validator.errorList).filter(e => e.element.id === input.id).length === 0;
                     // Fallback basic check (less robust)
                     // return input.checkValidity();
                }
                return true; // Step might not have an input or validation isn't needed
            }

            form.addEventListener('click', function(e) {
                if (e.target.classList.contains('next-btn')) {
                    if (validateCurrentStep()) {
                        if (currentStepIndex < steps.length - 1) {
                            currentStepIndex++;
                            updateStepUI();
                        }
                    }
                } else if (e.target.classList.contains('prev-btn')) {
                    if (currentStepIndex > 0) {
                        currentStepIndex--;
                        updateStepUI();
                    }
