            // Initialize UI
            updateStepUI();

            // Prevent form submission via Enter key unless it's the final submit action
            form.addEventListener('keydown', function(e) {
                if (e.key === 'Enter') {
                    const activeElement = document.activeElement;
                    // If Enter is pressed on an input field within an active step that is NOT the last step
                    if (activeElement.tagName === 'INPUT' && steps[currentStepIndex].contains(activeElement) && currentStepIndex < steps.length - 1) {
