void updateOledDisplay(DateTime t) {
  display.clearDisplay();
  display.setTextSize(2); // Taller text for time
  display.setCursor(0, 0);

  // Format time (HH:MM)
  char timeBuffer[6];
  snprintf(timeBuffer, sizeof(timeBuffer), "%02d:%02d", t.hour(), t.minute());
  display.print(timeBuffer);

  // Display AM/PM indicator (optional)
  // display.setTextSize(1);
  // display.print(t.hour() >= 12 ? " PM" : " AM");

  display.setTextSize(1); // Smaller text for details
  display.setCursor(0, 20); // Position for event name
  display.print("Event: ");
  display.print(currentEvent);

  display.setCursor(0, 35); // Position for night mode status
  display.print("Night TV: ");
  display.print(nightModeShort ? "1hr" : "2hr");

  display.setCursor(0, 50); // Position for time ratio
  display.print("Ratio: ");
  display.print(TIME_RATIO);
  display.print(":1");

  display.display(); // Push buffer to screen
}
