  async updateUserPermissions(userId: string, permissions: PermissionPayload): Promise<UserCredentials> {
    const payload = { ...permissions, id: userId }; // Combine payload with userId
    const response = await this.request.post("/users/v2/permissions", { data: payload });
    if (response.status() !== 200) {
      throw new Error(`API Error: Failed to update permissions for user ${userId}. Status: ${response.status()}, Body: ${await response.text()}`);
    }
    const json: UserCredentials = await response.json();
     if (!json.username || !json.password) {
        throw new Error('API Error: Permission update response did not contain username or password.');
    }
    return json;
  }

  /**
   * Orchestrates the creation of an admin user via API calls.
   * Encapsulates the multi-step setup process.
   * @param creationPayload - Payload for user creation.
   * @param permissionPayload - Payload for permission update.
   * @returns Admin user credentials.
   */
  async createAdminUser(creationPayload: UserCreationPayload, permissionPayload: PermissionPayload): Promise<UserCredentials> {
    const userId = await this.createUser(creationPayload);
    const credentials = await this.updateUserPermissions(userId, permissionPayload);
    return credentials;
  }
}

