The problem asks for the total area covered by the union of several rectangles, calculated modulo 10^9 + 7. Given the potentially large coordinates (up to 10^9) but a small number of rectangles (n <= 50), a sweep-line algorithm combined with y-coordinate discretization and a segment tree is a suitable approach. The prompt also hints at this by mentioning "线段树" (Segment Tree) in the chapter context.

**Algorithm:**

1.  **Event Points:** Represent each rectangle `[x1, y1, x2, y2]` by two events: a "start" event at `x1` for the interval `[y1, y2)` with type `+1`, and an "end" event at `x2` for the same interval `[y1, y2)` with type `-1`.
2.  **Discretization:** Collect all unique `y1` and `y2` coordinates. Sort them to get `discrete_y = {y'_0, y'_1, ..., y'_m}`. These points define `m-1` elementary intervals `[y'_i, y'_{i+1})`.
3.  **Segment Tree:** Build a segment tree over the indices `0` to `m-1`. Each node in the segment tree will correspond to a range of indices `[l, r)`, representing the actual y-range `[y'_l, y'_r)`. Each node should store:
    *   `count`: How many active rectangles *completely cover* this node's interval.
    *   `length`: The total length of the covered portion within this node's y-range `[y'_l, y'_r)`.
4.  **Sweep Line:**
    *   Sort all events by their x-coordinate.
    *   Initialize `total_area = 0` and `prev_x = events[0].x`.
    *   Iterate through the sorted events. For each event at `current_x`:
        *   Calculate the width of the vertical strip since the last event: `dx = current_x - prev_x`.
        *   Query the segment tree root for the total covered length (`covered_y_length`) along the y-axis just before processing the current event.
        *   Add the area of this strip to the total area: `total_area = (total_area + (dx % MOD) * (covered_y_length % MOD)) % MOD`. Use `long long` for intermediate calculations.
        *   Find the indices `y1_idx` and `y2_idx` in `discrete_y` corresponding to the event's `y1` and `y2`.
        *   Update the segment tree for the index range `[y1_idx, y2_idx)` with the event's `type` (+1 or -1). The update modifies the `count` values and recalculates the `length` values up the tree. The `length` of a node is `discrete_y[r] - discrete_y[l]` if `count > 0`, otherwise it's the sum of its children's lengths (or 0 for a leaf node with `count == 0`).
        *   Update `prev_x = current_x`.
5.  **Output:** Return `total_area`.

**C++ Implementation:**

```cpp
#include <iostream>
#include <vector>
#include <algorithm>
#include <map> // Or use lower_bound on sorted vector

using namespace std;

typedef long long ll;
const int MOD = 1e9 + 7;

// Structure for sweep-line events
struct Event {
    ll x;      // x-coordinate of the vertical line
    ll y1, y2; // y-interval [y1, y2)
    int type;  // +1 for start edge, -1 for end edge

    // Custom comparator for sorting events by x-coordinate
    bool operator<(const Event& other) const {
        if (x != other.x) return x < other.x;
        return type > other.type; // Optional: process starts before ends at same x
    }
};

// Segment tree node structure (implicit tree using arrays)
struct Node {
    int count = 0; // How many rectangles cover this segment entirely
    ll length = 0; // Length of the covered portion within this segment's y-range
};

// Global vector for discrete y-coordinates and segment tree
vector<ll> discrete_y;
vector<Node> tree;

// Update the segment tree for the y-interval [query_l, query_r)
// node_idx corresponds to the interval [l, r) in discrete_y indices
void update(int node_idx, int l, int r, int query_l, int query_r, int type) {
    // Base case: interval represented by node_idx is [discrete_y[l], discrete_y[r])
    if (query_l >= r || query_r <= l) { // Query interval outside node interval
        return;
    }
    if (query_l <= l && r <= query_r) { // Query interval covers node interval
        tree[node_idx].count += type;
    } else { // Query interval partially overlaps node interval
        int mid = l + (r - l) / 2;
        update(node_idx * 2, l, mid, query_l, query_r, type);
        update(node_idx * 2 + 1, mid, r, query_l, query_r, type);
    }

    // Recalculate the covered length for the current node
    if (tree[node_idx].count > 0) {
        // If covered by at least one rectangle, the length is the full interval length
        // Ensure r is within bounds before accessing discrete_y[r]
         if (r < discrete_y.size() && l < r) {
             tree[node_idx].length = discrete_y[r] - discrete_y[l];
         } else {
             tree[node_idx].length = 0; // Should not happen with correct indices
         }

    } else {
        // If not fully covered (count is 0)
        if (l + 1 == r) { // Leaf node
            tree[node_idx].length = 0;
        } else { // Internal node
             // Ensure children indices are valid before accessing
            int left_child = node_idx * 2;
            int right_child = node_idx * 2 + 1;
            if (right_child < tree.size()) { // Basic check
                 tree[node_idx].length = tree[left_child].length + tree[right_child].length;
            } else {
                 tree[node_idx].length = 0; // Avoid out-of-bounds
            }
        }
    }
     // Apply modulo if length needed modulo, but here length is physical, area is modulo
     // tree[node_idx].length %= MOD; // Not needed for length itself
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n;
    cin >> n;

    vector<Event> events;
    vector<ll> y_coords; // To collect all y-coordinates for discretization

    if (n == 0) {
        cout << 0 << endl;
        return 0;
    }

    for (int i = 0; i < n; ++i) {
        ll x1, y1, x2, y2;
        cin >> x1 >> y1 >> x2 >> y2;
        if (x1 < x2 && y1 < y2) { // Ensure valid rectangle
             events.push_back({x1, y1, y2, 1});
             events.push_back({x2, y1, y2, -1});
             y_coords.push_back(y1);
             y_coords.push_back(y2);
        }
    }

     if (events.empty()) {
         cout << 0 << endl;
         return 0;
     }

    // Discretize y-coordinates
    sort(y_coords.begin(), y_coords.end());
    y_coords.erase(unique(y_coords.begin(), y_coords.end()), y_coords.end());
    discrete_y = y_coords; // Assign to global variable

    int m = discrete_y.size();
    if (m <= 1) { // Need at least two y-coordinates to form intervals
         cout << 0 << endl;
         return 0;
    }

    // Resize segment tree (size depends on number of intervals m-1)
    tree.resize(4 * m); // Sufficient size for m points (m-1 intervals)

    // Sort events by x-coordinate
    sort(events.begin(), events.end());

    ll total_area = 0;
    // Initialize prev_x with the first event's x-coordinate
    ll prev_x = events[0].x;

    for (size_t i = 0; i < events.size(); ++i) {
        Event& current_event = events[i];

        // Calculate area contribution from the previous strip
        ll current_x = current_event.x;
        // Ensure dx is non-negative
        ll dx = max(0LL, current_x - prev_x);

        // Get total covered length from the root of the segment tree (node 1 represents [0, m-1))
        ll covered_y_length = tree[1].length;

        if (dx > 0 && covered_y_length > 0) {
            // Use long long for multiplication before modulo
            ll strip_area = (dx % MOD) * (covered_y_length % MOD);
            total_area = (total_area + strip_area) % MOD;
        }

        // Find indices in discrete_y for the event's y-interval
        // lower_bound returns iterator, subtract .begin() to get index
        int y1_idx = lower_bound(discrete_y.begin(), discrete_y.end(), current_event.y1) - discrete_y.begin();
        int y2_idx = lower_bound(discrete_y.begin(), discrete_y.end(), current_event.y2) - discrete_y.begin();

        // Update the segment tree for the interval [y1_idx, y2_idx)
        if (y1_idx < y2_idx) { // Ensure valid interval indices
             update(1, 0, m - 1, y1_idx, y2_idx, current_event.type);
        }

        // Update previous x for the next iteration
        prev_x = current_x;
    }

    // Ensure final result is non-negative
    cout << (total_area % MOD + MOD) % MOD << endl;

    return 0;
}
