#include <iostream>
#include <vector>
#include <algorithm>
#include <map> // Using map for easy unique sorted y-coords

using namespace std;

typedef long long ll;
const int MOD = 1e9 + 7;

// Event structure for sweep line
struct Event {
    ll x;
    ll y1, y2; // Original y-coordinates
    int type;  // +1 for start, -1 for end

    // Sort by x, then type (ends before starts at same x)
    bool operator<(const Event& other) const {
        if (x != other.x) {
            return x < other.x;
        }
        return type < other.type;
    }
};

// Segment Tree Node
struct Node {
    int count = 0;          // Coverage count for the node's interval
    ll covered_length = 0; // Length covered within this node's interval
};

vector<ll> y_coords_discrete; // Unique sorted y-coordinates
vector<Node> tree;           // Segment tree array

// Update covered_length based on count and children
void push_up(int node_idx, int l_range_idx, int r_range_idx) {
    if (tree[node_idx].count > 0) {
        // Fully covered by at least one rectangle
        tree[node_idx].covered_length = y_coords_discrete[r_range_idx] - y_coords_discrete[l_range_idx];
    } else if (r_range_idx - l_range_idx == 1) {
        // Leaf node, not covered
        tree[node_idx].covered_length = 0;
    } else {
        // Internal node, not fully covered, sum children
        tree[node_idx].covered_length = tree[node_idx * 2].covered_length + tree[node_idx * 2 + 1].covered_length;
    }
}

// Update segment tree for y-interval [update_l_idx, update_r_idx)
void update_tree(int node_idx, int l_range_idx, int r_range_idx, int update_l_idx, int update_r_idx, int type) {
    if (update_l_idx >= r_range_idx || update_r_idx <= l_range_idx) {
        return; // Update range outside node range
    }
    if (update_l_idx <= l_range_idx && r_range_idx <= update_r_idx) {
        // Update range covers node range completely
        tree[node_idx].count += type;
        push_up(node_idx, l_range_idx, r_range_idx);
    } else {
        // Partial cover, recurse
        int mid_idx = l_range_idx + (r_range_idx - l_range_idx) / 2;
        update_tree(node_idx * 2, l_range_idx, mid_idx, update_l_idx, update_r_idx, type);
        update_tree(node_idx * 2 + 1, mid_idx, r_range_idx, update_l_idx, update_r_idx, type);
        // Update current node after children are updated
        push_up(node_idx, l_range_idx, r_range_idx);
    }
}

