/**
 * @brief Calculates the shortest distance from a point P to a line segment [S1, S2].
 *
 * @param P The point.
 * @param S1 The start point of the line segment.
 * @param S2 The end point of the line segment.
 * @return The minimum distance from P to the segment [S1, S2].
 */
double distancePointSegment(Point P, Point S1, Point S2) {
    Point S1S2 = subtract(S2, S1); // Vector from S1 to S2
    Point PS1 = subtract(P, S1);   // Vector from S1 to P
    double segLenSq = lengthSquared(S1S2); // Squared length of the segment

    // Handle the case where the segment is just a point (S1 == S2)
    // Use a small epsilon for floating point comparison
    if (segLenSq < 1e-12) {
        return length(PS1); // Distance from P to S1
    }

    // Calculate the parameter t representing the projection of P onto the line containing the segment
    // t = dot(P - S1, S2 - S1) / ||S2 - S1||^2
    double t = dot(PS1, S1S2) / segLenSq;

    // Clamp t to the range [0, 1] to find the closest point on the segment itself
    t = std::max(0.0, std::min(1.0, t));

    // Calculate the closest point on the segment to P
    // ClosestPoint = S1 + t * (S2 - S1)
    Point closestPoint = add(S1, scale(S1S2, t));

    // Calculate the distance between P and the closest point on the segment
    Point P_Closest = subtract(P, closestPoint);
    return length(P_Closest);
}

/**
