 *
 * @param A The potentially covering SegmentShape.
 * @param B The potentially covered SegmentShape.
 * @return True if A completely covers B, false otherwise.
 */
bool isSegmentCovered(const SegmentShape& A, const SegmentShape& B) {
    // Condition 1: Width check
    // The covered segment cannot be wider than the covering segment.
    if (B.width > A.width) {
        return false;
    }

    // Calculate the maximum allowed distance from B's centerline points to A's centerline segment.
    // This accounts for the widths of both shapes.
    double max_allowed_distance = (A.width - B.width) / 2.0;

    // Condition 2: Check the distance from B.start to the centerline segment of A.
    double dist_B_start_to_A_centerline = distancePointSegment(B.start, A.start, A.end);
    if (dist_B_start_to_A_centerline > max_allowed_distance) {
