    if (dist_B_end_to_A_centerline > max_allowed_distance) {
        // If B's end point is too far from A's centerline (considering widths), B cannot be fully covered.
        return false;
    }

    // If all conditions are met, segment B is completely covered by segment A.
    return true;
}

