#include <cmath>
#include <algorithm> // For std::max, std::min
#include <limits>    // For epsilon comparison
#include <stdexcept> // For potential errors

const double EPSILON = 1e-9;

struct Point {
    double x, y;
};

struct Segment {
    Point start, end;
    double width;

    // Basic validation
    Segment(Point s, Point e, double w) : start(s), end(e), width(w) {
        if (width < 0) {
            throw std::runtime_error("Segment width cannot be negative.");
        }
    }
};

// Helper function: Squared Euclidean distance between two points
double distSq(const Point& p1, const Point& p2) {
    double dx = p1.x - p2.x;
    double dy = p1.y - p2.y;
    return dx * dx + dy * dy;
}

// Calculate the squared distance from point P to line segment [A, B]
double distancePointSegmentSq(const Point& P, const Point& A, const Point& B) {
    double lenSq = distSq(A, B);
    // Check if segment is a point
    if (lenSq < EPSILON * EPSILON) { 
        return distSq(P, A);
    }

    // Project P onto the line passing through A and B.
    // Parameter t = dot((P-A), (B-A)) / |B-A|^2
    double dotP = (P.x - A.x) * (B.x - A.x) + (P.y - A.y) * (B.y - A.y);
    double t = dotP / lenSq;

    // Clamp t to the range [0, 1] to ensure the projection point is on the segment
    t = std::max(0.0, std::min(1.0, t));

    // Calculate the closest point on the segment to P
    Point projection = {A.x + t * (B.x - A.x), A.y + t * (B.y - A.y)};

    // Return the squared distance from P to the projection point
    return distSq(P, projection);
}

// Calculate the distance from point P to line segment [A, B]
double distancePointSegment(const Point& P, const Point& A, const Point& B) {
    return std::sqrt(distancePointSegmentSq(P, A, B));
}

// Check if segment B is completely covered by segment A
bool isSegmentCovered(const Segment& A, const Segment& B) {
    // Condition 1: Width check
    // Use epsilon for floating point comparison robustness if needed, 
    // but B.width > A.width is generally safe.
    if (B.width > A.width + EPSILON) {
        return false;
    }

    // If widths are equal or B is thinner
    double radius = (A.width - B.width) / 2.0;
    // Radius should not be negative, but check due to potential floating point issues if widths are very close
    if (radius < 0) radius = 0; 

    // Condition 2a: Check distance for B's start point
    double dist_start = distancePointSegment(B.start, A.start, A.end);
    if (dist_start > radius + EPSILON) {
        return false;
    }

    // Condition 2b: Check distance for B's end point
    double dist_end = distancePointSegment(B.end, A.start, A.end);
    if (dist_end > radius + EPSILON) {
