// Structure to store character and its original index (1-based)
// Represents the character generated by an operation and the operation index.
struct CharInfo {
    char c;
    int index;

    // Comparison for finding minimum: smallest char, then smallest index
    bool operator<(const CharInfo& other) const {
        if (c != other.c) {
            return c < other.c;
        }
        return index < other.index;
    }
};

// Segment tree node structure
struct SegTreeNode {
    CharInfo min_char_info;
};

// Combine function for segment tree nodes
// Returns the node containing the lexicographically smaller character.
// If characters are equal, returns the one with the smaller operation index.
SegTreeNode combine(const SegTreeNode& left, const SegTreeNode& right) {
    return {std::min(left.min_char_info, right.min_char_info)};
}

// Build segment tree
// Initializes the leaf nodes with CharInfo for operations 1 to m.
// Then builds the internal nodes bottom-up.
void build(std::vector<SegTreeNode>& tree, int m, int tree_size) {
    // Initialize leaves for operations 1 to m
    for (int i = 0; i < m; ++i) {
        // Operation index is i+1 (1-based)
        // Character is 'a' + (i mod 26)
        tree[tree_size + i] = {{char('a' + (i % 26)), i + 1}};
    }
    // Initialize remaining leaves (padding) with a sentinel value
    // Character '{' is > 'z', index m+1 ensures it's never chosen unless the range is empty.
    for (int i = m; i < tree_size; ++i) {
        tree[tree_size + i] = {{'{', m + 1}};
    }
    // Build internal nodes by combining children
    for (int i = tree_size - 1; i > 0; --i) {
        tree[i] = combine(tree[i * 2], tree[i * 2 + 1]);
    }
}

// Query segment tree for minimum CharInfo in range [l, r] (1-based)
// Uses standard iterative segment tree query logic.
CharInfo query(std::vector<SegTreeNode>& tree, int tree_size, int m, int l, int r) {
    // Initialize results with sentinel values
    SegTreeNode res_left = {{'{', m + 1}};
    SegTreeNode res_right = {{'{', m + 1}};

    // Adjust query range [l, r] (1-based) to 0-based indices for leaf access
    l = l + tree_size - 1;
    r = r + tree_size - 1;

    // Iterative query process
    while (l <= r) {
        // If l is odd, it's a right child; include its node and move to the right sibling's parent.
        if (l % 2 == 1) {
            res_left = combine(res_left, tree[l]);
            l++;
        }
        // If r is even, it's a left child; include its node and move to the left sibling's parent.
        if (r % 2 == 0) {
            res_right = combine(tree[r], res_right);
            r--;
        }
        // Move up to the parent level
        l /= 2;
        r /= 2;
    }
    // Combine results from left and right parts of the query
    return combine(res_left, res_right).min_char_info;
}


