#include <iostream>
#include <vector>
#include <string>
#include <vector>
#include <queue>
#include <algorithm>

// Node structure for segment tree
struct Node {
    char min_char = '{'; // Character greater than 'z'
    int index = -1;      // 1-based index
};

// Combine function for segment tree nodes
Node combine(const Node& a, const Node& b) {
    if (a.min_char < b.min_char) return a;
    if (b.min_char < a.min_char) return b;
    // Tie-breaking: smaller index
    if (a.index == -1) return b;
    if (b.index == -1) return a;
    return (a.index < b.index) ? a : b;
}

// Build segment tree
void build(std::vector<Node>& tree, int m, int n_nodes) {
    // Initialize leaves
    for (int i = 0; i < m; ++i) {
        tree[n_nodes + i].min_char = 'a' + (i % 26);
        tree[n_nodes + i].index = i + 1; // 1-based index
    }
    // Build internal nodes
    for (int i = n_nodes - 1; i > 0; --i) {
        tree[i] = combine(tree[i * 2], tree[i * 2 + 1]);
    }
}

// Query segment tree for range [l, r] (1-based indices)
Node query(std::vector<Node>& tree, int n_nodes, int l, int r) {
    Node res_left, res_right;
    l = l + n_nodes - 1; // Adjust to 0-based leaf index + offset
    r = r + n_nodes - 1;
    while (l <= r) {
        if (l % 2 == 1) { // If l is right child
            res_left = combine(res_left, tree[l]);
            l++;
        }
        if (r % 2 == 0) { // If r is left child
            res_right = combine(tree[r], res_right);
            r--;
        }
        l /= 2;
        r /= 2;
    }
    return combine(res_left, res_right);
}


int main() {
