        }
    }

    int r = a_hash_indices.size();
    if (r == 0) {
        std::cout << a_str << "\n";
        return 0;
    }

    int L = m - r; // Number of '#' in b

    // Segment Tree Initialization
    int tree_size = 1;
    while (tree_size < m) {
        tree_size *= 2;
    }
    std::vector<Node> seg_tree(2 * tree_size);
    build(seg_tree, m, tree_size);

    std::vector<int> chosen_op_indices(r);
    int last_s = 0;

    for (int j = 0; j < r; ++j) {
        int current_j = j + 1; // 1-based j for formula
        int low = last_s + 1;
        int high = std::min((long long)L + current_j, m);

        if (low > high) {
             // This case should ideally not happen if logic is correct and m >= r
             // Handle potential error or edge case if necessary
