        }

        Node result = query(seg_tree, tree_size, low, high);
        chosen_op_indices[j] = result.index;
        last_s = result.index;
    }

    std::string final_a = a_str;
    for (int j = 0; j < r; ++j) {
        int original_index = a_hash_indices[j];
        int op_index = chosen_op_indices[j];
