// for Codeforces problem 1859D, which matches the prompt.
// This check determines if it's possible to achieve a state where the median is at least x.
// It relies on checking for local patterns of elements >= x in the original array.
bool check(const std::vector<long long>& a, int n, long long x) {
    std::vector<int> b(n);
    for (int i = 0; i < n; ++i) {
        b[i] = (a[i] >= x);
    }

    // Check if there exist adjacent elements >= x
    for (int i = 0; i < n - 1; ++i) {
        if (b[i] && b[i+1]) {
            return true;
        }
    }

    // Check if there exist elements >= x at distance 2
    for (int i = 0; i < n - 2; ++i) {
        if (b[i] && b[i+2]) {
            return true;
        }
    }

    return false;
}

