// Function to check if k is a valid base for a, b, c
// This function simulates the k-xor operation by checking digits iteratively.
// Assumes k >= 2.
bool isValidBase(long long k, long long a, long long b, long long c) {
    // Loop while any of the numbers a, b, or c are greater than 0.
    // This correctly handles cases where the numbers have different lengths in base k.
    while (a > 0 || b > 0 || c > 0) {
        // Get the least significant digits in base k
        long long digit_a = a % k;
        long long digit_b = b % k;
        long long digit_c = c % k;

        // Check the k-xor condition: (a_i + b_i) mod k == c_i
        if ((digit_a + digit_b) % k != digit_c) {
            // If the condition fails for any digit, k is not a valid base.
            return false;
        }

        // Move to the next digit by integer division (equivalent to right shift in base k)
        a /= k;
        b /= k;
        c /= k;
    }
    // If the loop completes without returning false, all digits satisfied the condition.
    // Therefore, k is a valid base.
    return true;
}

